import{_ as e}from"./plugin-vue_export-helper-DlAUqK2U.js";import{c as r,d as n,o as s}from"./app-DKtpHb63.js";const h={};function i(p,a){return s(),r("div",null,a[0]||(a[0]=[n('<h1 id="京东方医院合作项目沟通会" tabindex="-1"><a class="header-anchor" href="#京东方医院合作项目沟通会"><span>京东方医院合作项目沟通会</span></a></h1><h2 id="会议目标和议程" tabindex="-1"><a class="header-anchor" href="#会议目标和议程"><span>会议目标和议程</span></a></h2><h3 id="背景" tabindex="-1"><a class="header-anchor" href="#背景"><span>背景</span></a></h3><h4 id="合作背景" tabindex="-1"><a class="header-anchor" href="#合作背景"><span>合作背景</span></a></h4><h4 id="合作目的" tabindex="-1"><a class="header-anchor" href="#合作目的"><span>合作目的</span></a></h4><p>拟以京东方成都医院为第一主研单位，成都仁钦生物科技有限公司为合作单位，开展慢病和老年病的研究。<br> 包括：<br> 阿尔兹海默症、睡眠障碍、四高症等。</p><h4 id="合作原则" tabindex="-1"><a class="header-anchor" href="#合作原则"><span>合作原则</span></a></h4><h3 id="合作目标与范围" tabindex="-1"><a class="header-anchor" href="#合作目标与范围"><span>合作目标与范围</span></a></h3><h4 id="具体目标" tabindex="-1"><a class="header-anchor" href="#具体目标"><span>具体目标</span></a></h4><h4 id="研究范围和领域" tabindex="-1"><a class="header-anchor" href="#研究范围和领域"><span>研究范围和领域</span></a></h4><h3 id="合作方责任与义务" tabindex="-1"><a class="header-anchor" href="#合作方责任与义务"><span>合作方责任与义务</span></a></h3><h4 id="研究所的责任" tabindex="-1"><a class="header-anchor" href="#研究所的责任"><span>研究所的责任</span></a></h4><h4 id="医院的责任" tabindex="-1"><a class="header-anchor" href="#医院的责任"><span>医院的责任</span></a></h4><h4 id="双方共同责任" tabindex="-1"><a class="header-anchor" href="#双方共同责任"><span>双方共同责任</span></a></h4><h3 id="合作模式与流程" tabindex="-1"><a class="header-anchor" href="#合作模式与流程"><span>合作模式与流程</span></a></h3><h4 id="合作模式-如联合研究、资源共享等" tabindex="-1"><a class="header-anchor" href="#合作模式-如联合研究、资源共享等"><span>合作模式（如联合研究、资源共享等）</span></a></h4><h4 id="具体流程-如项目启动、中期检查、项目结束等" tabindex="-1"><a class="header-anchor" href="#具体流程-如项目启动、中期检查、项目结束等"><span>具体流程（如项目启动、中期检查、项目结束等）</span></a></h4><h3 id="资源与信息共享" tabindex="-1"><a class="header-anchor" href="#资源与信息共享"><span>资源与信息共享</span></a></h3><h4 id="资源分配" tabindex="-1"><a class="header-anchor" href="#资源分配"><span>资源分配</span></a></h4><h4 id="信息交流" tabindex="-1"><a class="header-anchor" href="#信息交流"><span>信息交流</span></a></h4><h3 id="成果评价与共享" tabindex="-1"><a class="header-anchor" href="#成果评价与共享"><span>成果评价与共享</span></a></h3><h4 id="成果评价标准" tabindex="-1"><a class="header-anchor" href="#成果评价标准"><span>成果评价标准</span></a></h4><h4 id="成果共享原则" tabindex="-1"><a class="header-anchor" href="#成果共享原则"><span>成果共享原则</span></a></h4><h3 id="知识产权与保密" tabindex="-1"><a class="header-anchor" href="#知识产权与保密"><span>知识产权与保密</span></a></h3><h4 id="知识产权归属" tabindex="-1"><a class="header-anchor" href="#知识产权归属"><span>知识产权归属</span></a></h4><h4 id="保密协议" tabindex="-1"><a class="header-anchor" href="#保密协议"><span>保密协议</span></a></h4><h3 id="风险管理与应对措施" tabindex="-1"><a class="header-anchor" href="#风险管理与应对措施"><span>风险管理与应对措施</span></a></h3><h4 id="风险预防" tabindex="-1"><a class="header-anchor" href="#风险预防"><span>风险预防</span></a></h4><h4 id="应对策略" tabindex="-1"><a class="header-anchor" href="#应对策略"><span>应对策略</span></a></h4><h3 id="财务条款" tabindex="-1"><a class="header-anchor" href="#财务条款"><span>财务条款</span></a></h3><h4 id="资金投入" tabindex="-1"><a class="header-anchor" href="#资金投入"><span>资金投入</span></a></h4><h4 id="费用分配" tabindex="-1"><a class="header-anchor" href="#费用分配"><span>费用分配</span></a></h4><h3 id="协议的修改与终止" tabindex="-1"><a class="header-anchor" href="#协议的修改与终止"><span>协议的修改与终止</span></a></h3><h4 id="修改条件" tabindex="-1"><a class="header-anchor" href="#修改条件"><span>修改条件</span></a></h4><h4 id="终止条件" tabindex="-1"><a class="header-anchor" href="#终止条件"><span>终止条件</span></a></h4><h3 id="争议解决" tabindex="-1"><a class="header-anchor" href="#争议解决"><span>争议解决</span></a></h3><h4 id="协商解决" tabindex="-1"><a class="header-anchor" href="#协商解决"><span>协商解决</span></a></h4><h4 id="法律途径" tabindex="-1"><a class="header-anchor" href="#法律途径"><span>法律途径</span></a></h4><h3 id="其他事项" tabindex="-1"><a class="header-anchor" href="#其他事项"><span>其他事项</span></a></h3><h4 id="协议的生效" tabindex="-1"><a class="header-anchor" href="#协议的生效"><span>协议的生效</span></a></h4><h4 id="附加条款" tabindex="-1"><a class="header-anchor" href="#附加条款"><span>附加条款</span></a></h4><h2 id="对方参会人员及专业背景" tabindex="-1"><a class="header-anchor" href="#对方参会人员及专业背景"><span>对方参会人员及专业背景</span></a></h2><p>对方负责人为由京东方成都医院副院长/血液科主任，参与的科室还包括神经内科、老年医学科和检验科。</p><h3 id="血液科" tabindex="-1"><a class="header-anchor" href="#血液科"><span>血液科</span></a></h3><p>血液内科是诊断、治疗淋巴造血系统良恶性疾病的临床学科。<br> 科室由门诊诊区、住院病区和专科实验室三部分组成。<br> 开展普通两人间病床48张，造血干细胞移植用无菌层流病床10张。<br> 拥有价值千万元的各类专科设备20余台 (套) 。</p><h4 id="王存邦" tabindex="-1"><a class="header-anchor" href="#王存邦"><span>王存邦</span></a></h4><p>副院长、主任；<br> 主任医师、医学博士、硕士研究生导师；<br> 毕业于第四军医大学，从事血液科临床一线工作30余年。<br> 曾就职中国人民解放军兰州军区总医院。<br> 曾担任中华医学会血液学专业委员会实验诊断学组委员，青年委员、中国康复医学会血液学康复专业委员会委员、甘肃省医师协会整合医学医师分会血液病专业委员会副主任委员、甘肃省医师协会血液学分会常委、甘肃省血液学专业委员会委员等。<br> 主持及参与完成国家、军队和甘肃省科研课题6项，以第1作者发表SCI收录、medline收录及核心期刊收录论文50余篇，出版专著2部。<br> 荣获甘肃省科技进步一、二、三等奖5项 (第1、2完成人) ，军队科技进步二、三等奖5项 (第1、2完成人) 。<br> 享受军队优秀专业技术干部岗位津贴9次。<br> 擅长领域为：造血干细胞移植治疗恶性血液病、恶性血液病的综合治疗、贫血类疾病的诊治。</p><h4 id="刘芳" tabindex="-1"><a class="header-anchor" href="#刘芳"><span>刘芳</span></a></h4><p>副主任医师、医学博士；<br> 博士毕业于北京大学医学部，美国内华达癌症研究所博士后，青年创新科技人才。<br> 曾就职中国人民解放军西部战区总医院任造血干细胞移植中心负责人。<br> 任四川省老年医学会血液病专业委员会副主任委员、四川省女医师协会血液专业委员会常务委员等职务。<br> 从事CAR-T细胞治疗，成果在2018年EHA、2018年ASH、2019年iwCAR、2019年ASH、2020年EHA大会发言。<br> 发表论文20余篇。<br> 擅长领域：<br> 造血干细胞移植，累积患者超过500例。</p><h4 id="欧剑锋" tabindex="-1"><a class="header-anchor" href="#欧剑锋"><span>欧剑锋</span></a></h4><p>副主任技师、医学博士；<br> 承担并参与军队及国家科研课题六项；发表学术论文二十三篇；获军队及省部级科技进步二、三等奖共五项；出版专著两部。<br> 擅长领域：血液病实验诊断的骨髓细胞形态分析；流式细胞术；基因检测技术；FISH技术及细胞培养、鉴定技术。</p><h4 id="吴静" tabindex="-1"><a class="header-anchor" href="#吴静"><span>吴静</span></a></h4><p>主治医师、医学学士；<br> 本科毕业于兰州大学，从事血液科临床一线工作多年。曾就职中国人民解放军兰州军区总医院。<br> 擅长领域：常见贫血、紫癜性疾病以及血液系统恶性疾病白血病、骨髓瘤等。</p><h3 id="神经内科学" tabindex="-1"><a class="header-anchor" href="#神经内科学"><span>神经内科学</span></a></h3><p>神经内科以神经急危重症的救治、神经系统常见病的规范化诊治和疑难病的个体化、多元化诊治为核心的综合性临床学科。<br> 神经重症、神经介入、超早期神经功能重建、智慧医疗、神经电生理、神经血管超声诊断等方向齐头并进。</p><h4 id="李敬诚" tabindex="-1"><a class="header-anchor" href="#李敬诚"><span>李敬诚</span></a></h4><p>主任；<br> 主任医师、医学博士、博士生导师、教授；<br> 原陆军军医大学陆军特色医学中心脑血管病医院副院长、神经内科副主任。<br> 本科、硕士及博士毕业于重庆医科大学，美国哈佛大学医学院(Harvard medical school) Fellowship，从事神经内科临床诊疗、科研工作30余年。<br> 历任重庆市中西医结合学会重庆神经介入分会主任委员，中华医学会神经病学分会感染性疾病与脑脊液细胞学学组委员，全军第九届医学科学技术委员会神经内科学专业委员会脑血管病介入学组委员，卫生部内镜临床诊疗质量评价专家委员会、卫生部全国医师定期考核内镜与微创专家委员会委员，卫生部医疗服务标准专业委员会专家库专家，中国抗癫痫学会重庆市抗癫痫学会第一届理事，中国医师学会重庆神经病学分会常委，中华医学会重庆神经病学分会神经介入组委员，国家自然基金一审评委，军队后勤科技评价专家，World Journal of Meta-Analysis、《中华医学杂志》等杂志编委。<br> 世界卒中组织 (World stroke organization) 会员。<br> 主研完成国家自然科学基金 ( NSFC) 项目3项，省部级及以上科研课题7项，获省部级科技进步一等奖2项、二等奖1项。<br> 副主篇专著5部，发表论文100余篇，其中以第一/通讯作者发表SCI论文45篇，影响因子大于5分6篇，平均影响因子4分。<br> 荣立集体二等功1次、个人三等功1次。<br> 擅长领域：<br> 研究重点为缺血性脑血管病与神经介入、帕金森氏病、神经系统疑难重症疾病等。<br> 在西南地区最早开展缺血性脑血管病与神经介入技术，具有全国影响力，2014年在全国颈动脉支架手术量排名第一。<br> 擅长颈动脉、椎动脉、颅内动脉、锁骨下动脉、肾动脉、下肢动脉等支架成型手术及急性缺血性脑血管病神经介入手术。<br> 参与“中国结核性脑膜炎专家共识”等多部专业指南、共识的起草，长期担任中央领导一级保健、重庆市高级领导保健工作，是全军、重庆市神经介入技术带头人。</p><h4 id="胡远兵" tabindex="-1"><a class="header-anchor" href="#胡远兵"><span>胡远兵</span></a></h4><p>副主任医师、医学硕士；<br> 本科及硕士毕业于第三军医大学，从事神经内科临床一线工作30余年，从事脑血管介入治疗20年。<br> 曾就职武警成都总医院任神经内科主任。<br> 武警部队老年病学专业委员会委员。<br> 获得全军科技进步二等奖1项 (第3作者) ，获武警部队科技进步二等奖1项 (第1作者) 。<br> 发表论文10余篇。<br> 擅长领域：<br> 在神经内科常见病疑难病诊治、急救、综合管理、康复治疗具有丰富经验，尤其擅长脑血管疾病的急救，脑血管瘤的介入治疗。</p><h4 id="王志强" tabindex="-1"><a class="header-anchor" href="#王志强"><span>王志强</span></a></h4><p>主治医师、医学博士；<br> 本科毕业于第四军医大学，硕士毕业于第三军医大学，博士毕业于成都中医药大学。<br> 从事神经内科疾病与神经介入治疗的临床、教学和科研工作10余年。<br> 曾就职中国人民解放军西部战区总医院、先后在天坛医院、宣武医院、华西医院培训学习。<br> 现任中华中医药学会脑病分会委员，中国医药教育协会介入微创治疗专业委员会青委会委员。<br> 参与国家、军队及省部级等课题4项，发表论文20余篇，其中SCI论文6篇。<br> 擅长领域：<br> 脑血管病的规范化诊疗，急性大血管闭塞性脑卒中血管再通术、颅内外动脉狭窄血管成形术、阿尔茨海默病、卒中后神经功能障碍性疾病、睡眠障碍的中西医结合治疗。</p><h4 id="黄亮" tabindex="-1"><a class="header-anchor" href="#黄亮"><span>黄亮</span></a></h4><p>主治医师、医学硕士；<br> 本科毕业于南昌大学，研究生毕业于桂林医学院，从事神经内科的临床工作多年。<br> 曾就职中国人民解放军陆军军医大学第三附属医院。<br> 参与国家级、市级自然科学基金的多项研究，发表论文2篇。<br> 擅长领域：<br> 对神经科常见病、多发病的诊断和治疗具有较丰富的临床经验，尤其擅长脑血管病、神经系统感染性疾病、癫痫、头痛、帕金森病等疾病的诊治。</p><h4 id="李余霞" tabindex="-1"><a class="header-anchor" href="#李余霞"><span>李余霞</span></a></h4><p>主治医师、医学学士；<br> 毕业于成都医学院，从事临床工作10年。<br> 曾就职中国人民解放军西部战区总医院。<br> 现任四川省医学会神经电生理专业学组委员、四川省预防医学会卒中预防与控制分会委员。<br> 获得实用新型专利两项，获得发明专利、实用新型专利3项，参编由人民卫生出版社出版专著1部，参与发表论文多篇。<br> 擅长领域：<br> 脑血管病，神经电生理诊断技术，头晕，头痛，睡眠障碍等疾病的诊治。</p><h4 id="杨江琴" tabindex="-1"><a class="header-anchor" href="#杨江琴"><span>杨江琴</span></a></h4><p>住院医师、医学硕士；<br> 本科及硕士毕业于西南医科大学，从事神经内科临床工作多年。<br> 曾就职成都市第三人民医院。<br> 发表核心期刊2篇。<br> 擅长领域：<br> 在神经内科常见病及多发病的诊治具有丰富经验，尤其擅长脑梗死脑缺血等脑血管病、记忆力下降、痴呆、头昏头痛及睡眠障碍等疾病的诊治。</p><h4 id="李家琪" tabindex="-1"><a class="header-anchor" href="#李家琪"><span>李家琪</span></a></h4><p>住院医师、医学硕士；<br> 本科及硕士毕业于哈尔滨医科大学，从事神经内科多年。<br> 曾就职哈尔滨医科大学附属第二医院、四川省人民医院。<br> 发表核心期刊论文1篇。<br> 擅长领域：<br> 脑血管病的规范化诊疗；中枢神经系统脱髓鞘疾病的规范化治疗；头疼、头晕疾病的鉴别与诊治。</p><h4 id="孙花容" tabindex="-1"><a class="header-anchor" href="#孙花容"><span>孙花容</span></a></h4><p>主治医师、医学学士；<br> 本科毕业于成都医学院，从事神经内科临床一线工作多年。<br> 曾就职中国人民解放军西部战区总医院、四川省第二中医医院。<br> 擅长领域：<br> 在神经科各种常见病及多发病的诊治具有丰富经验，尤其擅长神经危重症疾病的诊治，尤其擅长腰椎穿刺术、腰大池置管术、气管切开术、脑室穿刺外引流术等及熟悉呼吸机的使用。</p><h3 id="检验科" tabindex="-1"><a class="header-anchor" href="#检验科"><span>检验科</span></a></h3><p>医学检验科系集临床实验诊断、健康体检及区域检验于一体的综合性临床平台学科。<br> 其中业务用房面积6000余平米，设置临床基础检验、临床生化检验、临床免疫检验、临床微生物检验、临床分子诊断与精准医学检验、细胞功能与形态学检验、性病与艾滋病初筛实验室等亚专业，配置罗氏生化-免疫检验流水线、罗氏MP96全自动核酸检测工作站及LC480PCR仪、罗氏Cobas u6500全自动尿液分析流水线 (二条) 、希森美康Cs5100全自动凝血分析仪 (二台) 、梅里埃BacT/Alert240全自动微生物培养鉴定及药敏分析系统、西门子BN-II特定蛋白分析仪、SEBIA CAPILLARYS 3全自动蛋白电泳分析仪、Roller 20全自动血沉仪 (二台) 、沃芬GEM3500血气分析仪 (二台) 、欧蒙EUR0Lotone全自动免疫印迹仪、迈瑞Cal8000(211)血细胞分析流水线、迈瑞CL6000I全自动化学发光仪、迈瑞BriCyte E6流式细胞分析仪以及全自动粪便分析仪、全自动精液分析仪、全自动阴道分泌物分析仪、全自动微量元素分析仪、相差显微镜、荧光显微镜等先进检测设备，拥有以博士、博士生导师为学科带头人的专业技术团队，技术人员共25人，其中高级职称5人、中级10人，开展检测项目800余项。</p><h3 id="老年医学科" tabindex="-1"><a class="header-anchor" href="#老年医学科"><span>老年医学科</span></a></h3><p>老年医学科是医院重点学科，是以老年性疾病诊治、研究和教学为主体的综合性临床学科，是老年病防治、研究和人才培养基地，拥有一流的医疗护理团队。</p><h2 id="研究和工作基础" tabindex="-1"><a class="header-anchor" href="#研究和工作基础"><span>研究和工作基础</span></a></h2><p>(项目经验、专业技能、研究成果或设备资源等)</p><h3 id="睡眠障碍" tabindex="-1"><a class="header-anchor" href="#睡眠障碍"><span>睡眠障碍</span></a></h3><h3 id="计算生物医学平台" tabindex="-1"><a class="header-anchor" href="#计算生物医学平台"><span>计算生物医学平台</span></a></h3><p>根据文献检索关键词聚类的结果，我们拟定在三个方面进行，<br> 其一是计算建模，<br> 针对睡眠障碍和长期新冠病毒病，<br> 建立计算机辅助疾病预测模型。<br> 其二是计算组学，<br> 研究中草药成分与基因靶点/疾病的关联性。<br> 其三是机器学习辅助的个体化健康管理，<br> 在前两方面研究的基础上，进行疾病预测/细分，并提供用药或过继性回输的建议。</p><h3 id="生物信息学和机器学习" tabindex="-1"><a class="header-anchor" href="#生物信息学和机器学习"><span>生物信息学和机器学习</span></a></h3><h2 id="计算机辅助疾病预测模型" tabindex="-1"><a class="header-anchor" href="#计算机辅助疾病预测模型"><span>计算机辅助疾病预测模型</span></a></h2><p>辅助诊断疾病模型旨在根据病历或者病情描述给出诊断疾病的提示，<br> 目前的趋势是采用机器学习/深度学习方法，<br> 构建的过程基于病历和病情描述。<br> 学习过的病历数越多，<br> 模型的准确度通常会越高，<br> 超越传统的通过规则和统计的辅助诊断方法。</p><p>传统的通过规则和统计的辅助诊断疾病方法，<br> 其原理是识别关键信息。<br> 以规则为例，<br> 该方法通常采用是一套复杂的决策体系，<br> 是一套大量的存在何种情况就走哪条判别路径的规则系统，<br> 典型的就是以《临床指南》作为原始规则素材，<br> 将与或非逻辑转换为代码，<br> 写成一套系统。<br> 以统计为例，<br> 该方法通常采用贝叶斯方法，<br> 识别病历中的关键词，<br> 例如症状等，<br> 通过计算这些关键词在全量病历中对应哪种诊断最多，<br> 给出概率最大的诊断。<br> 以上两种传统方法都有明显的不足。<br> 规则方法过于死板，<br> 规则难以穷尽，<br> 规则之间错综复杂的关系难以梳理，<br> 并固定为程序。<br> 统计方法最多只能统计有限个关键词，<br> 对于表述的多样性无能为力，<br> 而且常用的朴素贝叶斯方法有一个独立事件的强假设与现实世界不相符。</p><p>辅助诊断疾病模型的基本建立方法分为6步。<br> 第一步是定义好可诊断疾病的范围。<br> 第二步是病历的向量化。<br> 病历中的主诉、现病史、既往史、检验、体格检查、性别、年龄等信息将会被拼接成一个向量化的序列。<br> 第三步是将病历分为训练集和验证集。<br> 第四步是将病历分批，<br> 按批次进行训练。<br> 第五步是将病历训练多轮。<br> 第六步是中止训练。<br> 随着训练推进，<br> 误差已经越来越小，<br> 最终维持在一个不能再下降的水平。<br> 此时就是结束训练的时刻，<br> 如果继续训练，<br> 模型参数会在训练集上过拟合，<br> 训练集上误差下降的同时，<br> 在验证集上误差增加。<br> 模型参数到此刻就被固定下来，<br> 保存为一个被称为模型的文件。</p><h2 id="利用系统生物学研究中草药成分、靶点和作用机制" tabindex="-1"><a class="header-anchor" href="#利用系统生物学研究中草药成分、靶点和作用机制"><span>利用系统生物学研究中草药成分、靶点和作用机制</span></a></h2><h2 id="靶点蛋白结构分析" tabindex="-1"><a class="header-anchor" href="#靶点蛋白结构分析"><span>靶点蛋白结构分析</span></a></h2><h3 id="分子对接" tabindex="-1"><a class="header-anchor" href="#分子对接"><span>分子对接</span></a></h3><h3 id="qsa分析" tabindex="-1"><a class="header-anchor" href="#qsa分析"><span>QSA分析</span></a></h3><p>蛋白构效分析</p><h2 id="个体化健康管理" tabindex="-1"><a class="header-anchor" href="#个体化健康管理"><span>个体化健康管理</span></a></h2><h1 id="可行性分析" tabindex="-1"><a class="header-anchor" href="#可行性分析"><span>可行性分析</span></a></h1><h2 id="已具备的技能" tabindex="-1"><a class="header-anchor" href="#已具备的技能"><span>已具备的技能</span></a></h2><p>团队专业背景包括但不限于检验医学、细胞生物学和分子生物学，计算机科学和公共卫生学。<br> 主要工作人员已经完成的相关课程或培训包括：<br> R语言、<br> 初级Python(Python for beginners)、<br> 中级Python (Intermediate python)、<br> Python核心(Python core)、<br> 用于数据结构的Python(Python for data structures)、<br> 用于数据科学的Python (Python for data science)、<br> SQL语言、<br> 数据科学(Data science)、<br> 机器学习(Machine learning)、<br> Ruby语言、<br> 网页开发基础(Web development fundamentals)、<br> 超文本标记语言(HTML)、<br> 层叠样式表(CSS)、<br> Javascript语言、<br> Jquery框架<br> 以及<br> 响应式网页设计(Responsive Web Design)。</p><h3 id="r语言" tabindex="-1"><a class="header-anchor" href="#r语言"><span>R语言</span></a></h3><p>R是用于统计分析、绘图的语言和操作环境。<br> 其功能包括：<br> 数据存储和处理系统；<br> 数组运算工具(其向量、矩阵运算方面功能尤其强大)；<br> 完整连贯的统计分析工具；<br> 优秀的统计制图功能。<br> R还是一种简便而强大的编程语言：<br> 可操纵数据的输入和输出，<br> 可实现分支、循环，<br> 用户可自定义功能。</p><p>我们将其用于数据清洗和处理、统计分析和信息可视化。<br> 联合Cytoscape进行蛋白质互作网络分析。</p><h3 id="python语言" tabindex="-1"><a class="header-anchor" href="#python语言"><span>Python语言</span></a></h3><p>Python是一种灵活多用的计算机程序设计语言，<br> 提供了很多的重要库，<br> 包括：<br> Numpy、Pandas、Matplotlib、Scipy、scikit-learn等。<br> 这些库为Python提供了数值计算需要的多种的数据结构、算法、接口以及多种的机器学习库函数和用于制图和可视化的必备操作等等。<br> 这些功能都使得Python用起来更为方便，<br> 是目前解决数据挖掘、数据分析和机器学习问题的最常用的工具。</p><p>我们利用Python来进行数据分析和机器学习，<br> 包括聚类、决策树模型、随机森林模型和神经网络。</p><h3 id="ruby语言" tabindex="-1"><a class="header-anchor" href="#ruby语言"><span>Ruby语言</span></a></h3><p>Ruby是一种开源的面向对象程序设计的服务器端脚本语言，<br> 在20世纪90年代中期由日本的松本行弘(まつもとゆきひろ/Yukihiro Matsumoto)设计并开发。</p><p>我们使用的是基于该语言的RAKE和Jekyll。<br> RAKE(Ruby mAKE)是一个用Ruby实现的类似GNU Make的程序。<br> GNU Make is a tool which controls the generation of executables and other non-source files of a program from the program&#39;s source files.<br> 而Jekyll是一个静态网站生成器。</p><h3 id="lisp语言" tabindex="-1"><a class="header-anchor" href="#lisp语言"><span>LISP语言</span></a></h3><p>LISP名称源自列表处理(LISt Processing)的英语缩写，<br> LISP是一种通用高级计算机程序语言，<br> 由来自麻省理工学院的人工智能研究先驱约翰·麦卡锡(John McCarthy)在1958年基于λ演算所创造，<br> 采用抽象数据列表与递归作符号演算来衍生人工智能 。<br> 作为应用人工智能而设计的语言，<br> Lisp是第一个声明式系内函数式程序设计语言，<br> 有别于命令式系内过程式的C、Fortran和面向对象的Java、C#等结构化程序设计语言。<br> Lisp有很多种方言，<br> 广被应用于软件开发、电子商务及金融系统的有Common Lisp、Scheme、Emacs Lisp和Clojure等。</p><p>目前我们使用的方言是Emacs和Racket。</p><h3 id="sql语言" tabindex="-1"><a class="header-anchor" href="#sql语言"><span>SQL语言</span></a></h3><p>SQL是结构化查询语言(Structured Query Language)的缩写，<br> 是一种在数据库管理系统(Relational Database Management System，RDBMS)中查询数据，<br> 或通过RDBMS对数据库中的数据进行更改的语言。</p><p>目前我们已经在开始建立睡眠障碍和抑菌抗病毒有效成分相关的草药数据库。</p><h3 id="机器学习-machine-learning" tabindex="-1"><a class="header-anchor" href="#机器学习-machine-learning"><span>机器学习(Machine Learning)</span></a></h3><p>机器学习是一门多领域交叉学科，<br> 涉及概率论、统计学、逼近论、凸分析、算法复杂度理论等多门学科。<br> 专门研究计算机怎样模拟或实现人类的学习行为，<br> 以获取新的知识或技能，<br> 重新组织已有的知识结构使之不断改善自身的性能。<br> 它是人工智能的核心，<br> 是使计算机具有智能的根本途径。</p><p>理解某种疾病的某种现象仅使用单种数据类型是远远不够的，<br> 随着高通量测序和多组学的快速发展，<br> 生物医学研究开始采取多组学技术结合的方法，<br> 传统的信息数据处理算法不能满足大数据的处理要求，<br> 机器学习作为从数据中进行学习的算法，<br> 可以对不同组学来源(如基因组学、转录组学、蛋白质组学、代谢组学)的数据进行综合分析，<br> 开发针对个体多样性的多因素预测模型，<br> 可以显著减少需要考虑的潜在治疗组合的空间，<br> 并识别其他可能被忽视的组合，<br> 并可以添加实验验证的步骤，<br> 以提供额外的证据，<br> 从而证明预测治疗可能存在的有效性。<br> 机器学习在疾病亚型识别、生物标志物发现、通路分析以及药物发现及其再利用有着更广泛的前景和应用空间。</p><p>目前我们已经建立了基于python scikit-learn的机器学习模块，<br> 研究方向主要包括决策树、随机森林、人工神经网络、贝叶斯学习等方面的研究。</p><h2 id="已有方法或研究模块" tabindex="-1"><a class="header-anchor" href="#已有方法或研究模块"><span>已有方法或研究模块</span></a></h2><p>在以往工作的基础上，<br> 我们建立了最适合本团队的方法学、技术架构和工作流(workflow)。<br> 下列带有后缀(-tron)的模块为自主研发或改良的方法/技术。</p><h3 id="泛文本处理模块-utkastron" tabindex="-1"><a class="header-anchor" href="#泛文本处理模块-utkastron"><span>泛文本处理模块(Utkastron)</span></a></h3><p>我们利用Bash、RAKE、JavaScript(Gulp.js)和VBA等编程语言将现有的种文本编辑工具整合在一起，建立了兼容多种文本格式的泛文本处理模块。<br> 最大的便利之处是半自动化，只需要编辑思维导图(Freeplane)，就可以获得markdown格式、org格式和docx格式的文本。</p><p>文本编辑和处理是现代社会工作每天都要面对的，<br> 最常用的工具包括：<br> 微软office(Windows系统)、open office(Linux系统)和pages文稿(Mac系统)。<br> 这些软件存在的最大的问题是界面复杂、功能冗余、格式调整繁琐和难以版本控制。<br> 其它可选的文本编辑工具还有Emacs和Vim等，但技术门槛比较高，同时学习曲线也比较陡峭。</p><p>我们的泛文本处理模块的意义在于，<br> markdown文件可以直接用于Jekyll或Vuepress框架，完成网页的部署。<br> org格式的文件可以纳入基于Lisp的orgmode日程管理系统。<br> docx格式的文件可以通过该模块的vba macro直接完成格式调整。</p><h3 id="系统药理学分析模块-pharmaktron" tabindex="-1"><a class="header-anchor" href="#系统药理学分析模块-pharmaktron"><span>系统药理学分析模块(Pharmaktron)</span></a></h3><p>我们根据已发表的论文和现有技术方案开发了R语言脚本(Script)来进行系统药理学研究。<br> 现有的网络药理学研究基本扎堆于中药成分/靶点/疾病分析和预测。<br> 其中还有很多误用分析方法或可视化方法，<br> 例如，直接用数据库中检索的成分和靶点进行分子对接，或者采用桑基图来表示成分、靶点和疾病关系(存疑)。</p><h3 id="蛋白质结构分析模块" tabindex="-1"><a class="header-anchor" href="#蛋白质结构分析模块"><span>蛋白质结构分析模块</span></a></h3><p>在以往研究的基础上，我们改良了蛋白质结构分析的方法。<br> 目前的分析模块包括：同源建模、分子动力学、NMA分析和分子对接。</p><p>Deepmind的Alphago系列颠覆了围棋领域，AlphaFold和AlphaFold2则颠覆了蛋白质结构预测领域。<br> 当今的一种观点认为，重头建模已经没有意义了，不管是预测准确性还是运算时间都没有优势，但同源建模还是有用处，即用于分子动力学前的分子结构修复。<br> 我们利用同源建模来修补PDB文件的缺失部分，然后进行分子动力学模拟。</p><p>由于算力的原因，目前的分子动力学模拟还处于条件摸索阶段，于是我们转向NMA来获取不同的蛋白质构象。<br> 通过对不同的构象进行分子对接，我们获得了一些结果，在后续研究中可能会揭示草药成分和靶点以及疾病的相关机制。</p><h3 id="关联网络分析模块-netzwerktron" tabindex="-1"><a class="header-anchor" href="#关联网络分析模块-netzwerktron"><span>关联网络分析模块(Netzwerktron)</span></a></h3><p>我们利用Rcy3和Cytoscape建立了关联网络分析方法。<br> 包括蛋白质--蛋白质相互作用网络和医学主题词关系网络。</p><h3 id="信息可视化模块-visuatron" tabindex="-1"><a class="header-anchor" href="#信息可视化模块-visuatron"><span>信息可视化模块(Visuatron)</span></a></h3><p>我们利用R或者Python语言对数据集进行分析并绘图。<br> 目前常用的主要有散点图、柱状图、饼图、箱型图、ROC曲线、韦恩图(Venn/UpsetR)、桑基图、气泡图、热图等。</p><h2 id="前期工作" tabindex="-1"><a class="header-anchor" href="#前期工作"><span>前期工作</span></a></h2><p>详见之前的工作报告和Powerpoint文档。</p><h1 id="衰老相关疾病" tabindex="-1"><a class="header-anchor" href="#衰老相关疾病"><span>衰老相关疾病</span></a></h1><p>Aging is the major risk factor for cancer, cardiovascular disease, diabetes, and neurodegenerative disorders.<br> Although we are far from understanding the biological basis of aging, research suggests that targeting the aging process itself could ameliorate many age-related pathologies.<br> Senescence is a cellular response characterized by a stable growth arrest and other phenotypic alterations that include a proinflammatory secretome.<br> Senescence plays roles in normal development, maintains tissue homeostasis, and limits tumor progression.<br> However, senescence has also been implicated as a major cause of age-related disease.<br> In this regard, recent experimental evidence has shown that the genetic or pharmacological ablation of senescent cells extends life span and improves health span.<br> Here, we review the cellular and molecular links between cellular senescence and aging and discuss the novel therapeutic avenues that this connection opens.<br> 衰老是许多慢性疾病或残疾最主要的危险因素,包括中风、心脏病、癌症、痴呆、骨质疏松、代谢综合征、肾功能衰竭、失明等。<br> 新的发现表明，衰老是一种可改变的危险因素,通过调节基本的衰老机制来推迟衰老相关疾病是可行的。<br> 细胞衰老通过SASP导致慢性炎症。<br> 回顾诱导衰老和SASP的机制，它们与慢性疾病和生理衰弱相关联，临床干预可以以细胞衰老和SASP作为治疗目标,根据不同的疾病，找准对应靶点，制定有效的治疗方案。<br> 通过研究找出控制炎性衰老相关基因，从而作为靶点进行药物干预，切断炎症触发因子来延缓多种年龄相关慢性疾病的发病，则能改善衰老机体的健康，并降低随着老龄化人口增长所带来的医疗保健费用，具有重要的社会学意义。</p><h2 id="衰老相关分泌表型-sasp" tabindex="-1"><a class="header-anchor" href="#衰老相关分泌表型-sasp"><span>衰老相关分泌表型(SASP)</span></a></h2><p>细胞衰老发生于受损细胞，并防止其在生物体增殖。<br> 细胞损伤本身并不直接导致明显的衰老迹象，而是当损伤累积和达到一定的限度，细胞停止增殖,导致肉眼可见的组织衰弱和生理上的衰老表型。</p><p>SASP的概念是由Coppe等在2008年首次提出的，研究发现衰老细胞能通过分泌炎症及癌基因相关因子促进邻近癌前细胞发生癌变，并称这些因子为SASP。<br> 衰老细胞在各个器官积累的同时伴随一系列复杂的SASP，它是不同种类细胞因子的表达和分泌明显增加的表型,是衰老细胞产生的最重要的环境效应。<br> SASP包括促炎细胞因子(如IL-1α、IL-1β、IL-6和IL-8)，生长因子(如HGF、TGF-β和GM-CSF),趋化因子(如CXCL-1/3和CXCL-10)和基质重塑酶(如金属蛋白酶)等，SASP的构成成分诱导出的不同的生物学活性表明它与其他细胞作用并构成一个机制调节组织局部微环境，可能导致或加剧衰老相关疾病。</p><p>SASP虽然是衰老细胞的共同特征，但不同刺激诱导的衰老或不同种类细胞其SASP成分的表达各有差异。<br> 如复制衰老、阿霉素诱导衰老、H2O2诱导衰老和5-氮-2′-脱氧胞苷诱导衰老，这4种衰老共同的通路与炎症和先天免疫系统有关，转录组测序分析表明,SASP是所有4种衰老的一种共同特征。<br> 而复制性衰老(RS)、压力诱导早衰(SIPS)和蛋白酶体抑制诱导早衰(PIIPS)中，RS和SIPS较PIIPS 衰老相关分泌表型特征更为明显。<br> SIPS和RS中SASP大部分细胞因子分泌增加，而在PIIPS中只有小部分分泌增加。<br> 这说明衰老相关的分泌表型取决于不同的衰老诱导刺激。<br> 尽管SASP的组成成分取决于不同的细胞和环境，但在不同种类的细胞中仍有一些基础的重叠部分，例如，IL-6和IL-8是最固定的因子，能刺激血管新生，破坏细胞信号传导，阻碍巨噬细胞功能，诱导固有免疫应答，促进上皮和内皮细胞迁移和侵袭。<br> 肝细胞SASP除了特征因子IL-8和IL-6外，则出现了新的成分如SAA4、IL-32和纤维蛋白原。</p><p>衰老和SASP与免疫关系密切。<br> 目前认为衰老细胞积累是免疫监视缺陷的结果，因为当使用免疫刺激剂时衰老细胞的去除率将明显升高。<br> 最近的一些研究表明自噬和SASP有密切的关联，自噬可以减弱由SASP高蛋白合成率所引起的蛋白毒性压力。<br> SASP与衰老所带来的毒副作用有关，并且通过自分泌和旁分泌增强表型，SASP也免疫性清除一些衰老细胞。</p><h2 id="sasp的生物学功能" tabindex="-1"><a class="header-anchor" href="#sasp的生物学功能"><span>SASP的生物学功能</span></a></h2><p>SASP有一个为人熟知的生物学功能便是促肿瘤效应，人类衰老成纤维细胞可以促进癌变前或恶性上皮细胞在体外增殖和在体内形成肿瘤。<br> 在某种程度上，这种功能是受被增殖衰竭、致癌基因Ras、p14ARF或过氧化氢等刺激的衰老细胞所分泌的可溶或不可溶的细胞因子所促进。<br> 此外，SASP对由基因毒性所导致的干细胞样癌症细胞的出现、保持和转移有促进作用。<br> 这些都有助于解释SASP的促肿瘤效应。<br> 在癌变前细胞中，p53的损失或增加致癌的Ras都会加剧SASP的致瘤效果，包括上皮间质转换和侵袭，这些可能与IL-6和IL-8的旁分泌调节有关。</p><p>SASP具有双面性，在促肿瘤的同时，一些SASP成分反而对衰老反应的肿瘤抑制起作用。<br> 例如,IL-6、IL-8、IGFBP7、GROα 和WNT16B在致癌基因激活后，加强细胞的衰老状态,防止恶变。</p><p>SASP除了促肿瘤，改变组织微环境，进一步促进衰老这些消极的方面外，对人体也有有益的一面。<br> 例如激活免疫系统，促进伤口愈合和组织修复，加强衰老逮捕,引发衰老细胞的免疫监控；<br> 与表观遗传调控协同作用，维持一个稳定的衰老表型；<br> 通过分泌血小板衍生生长因子AA(PDGF-AA)诱导肌纤维细胞分化，从而加速伤口闭合。<br> 衰老也是一种发育机制，有助于胚胎的发育和成形，胚胎发育伴随着细胞衰老和SASP,衰老细胞通过SASP分泌各种细胞因子，有助于组织的构建和重塑，这也帮助我们理解SASP进化的原因。</p><h2 id="sasp分泌的调节" tabindex="-1"><a class="header-anchor" href="#sasp分泌的调节"><span>SASP分泌的调节</span></a></h2><p>研究显示，一些物质或基因会上调细胞SASP相关因子的分泌。<br> 经过LPS处理的骨髓基质血管细胞也出现SASP,TNF-α、IL-1β、IL-6、MCP-1和VEGF的表达均升高。<br> HuR不仅调节复制寿命,也调节小鼠成纤维细胞SASP相关细胞因子的表达，RNAi-介导的HuR抑制导致SASP相关细胞因子的增加。<br> 果蝇成虫上皮细胞中，线粒体功能障碍或激活Ras可以导致细胞衰老和SASP。<br> PKCη通过上调细胞周期抑制剂p21Cip1和 p27Kip1的表达和增强IL-6的转录和分泌来促进衰老,然而 IL-8的表达则受PKCη的特殊抑制。</p><p>基于SASP大部分发挥的都是促进慢性炎症、促衰老及加速肿瘤发展等作用，研究如何抑制SASP的发展和分泌，有助于延缓衰老和衰老相关疾病。</p><p>TNF-α是SASP的主要组成成分，生物治疗药物阿达木单抗(adalimumab)是可以直接抑制TNF-α的单克隆抗体，它可以抑制SASP的分泌，使IL-6的释放量明显减少，eNOS和miR-126-3p的表达水平明显增高。<br> 阿达木单抗还可以诱导衰老细胞的表观遗传修饰，从而减弱SASP的促癌作用。</p><p>研究表明，某些特定的黄酮类化合物可以抑制SASP的产生，部分和NF-κB p65以及 IκBζ信号通路有关，可以有效地保护或减轻退行性疾病(如心血管疾病和晚期癌症)中的慢性低度炎症。<br> 天然黄酮类化合物芹黄素和山柰酚可以强烈抑制SASP的表达，这些类黄酮通过IRAK1/IκBα的信号通路上调IκBζ表达,从而抑制NF-κB p65活性。<br> 抑制IκBζ表达则会减少SASP的表达。<br> 体内实验中，口服芹黄素可以使老年大鼠肾脏中SASP明显降低，并升高IκBζ mRNA的水平。</p><p>JAK抑制剂可以减少脂肪前体细胞和脐静脉内皮细胞(HUVEC)中SASP的分泌,由此推断JAK 通路可能是对抗衰老相关功能障碍的一个潜在靶点。<br> TRIM28对IL-6、IL-8和其他SASP的成分有正向调节的作用,当TRIM28耗尽，分泌表型则受到强烈的抑制。</p><p>辛伐他汀是HMG-CoA还原酶抑制剂，现在已知可以减缓炎症，防止某些癌症。<br> 研究表明，辛伐他汀通过抑制蛋白质异戊烯化，降低衰老人成纤维细胞的SASP，而不影响衰老生长停滞。<br> 同时，辛伐他汀可以减轻衰老的条件培养基对乳腺癌细胞增殖和内分泌耐药的影响。</p><p>最近研究表明，mTOR抑制剂雷帕霉素是一个强有力的SASP抑制剂。<br> mTOR通过调节IL-1α和MAPKAPK2的翻译来控制SASP，反过来，在衰老过程中，p38下游信号MAPKAPK2磷酸化RNA结合蛋白ZFP36L1，从而防止SASP转录物的降解。<br> 当mTOR抑制时，ZFP36L1降低SASP转录和废除IL-1α反馈环路。<br> 所以，p38MAP激酶和MK2的小分子抑制剂可以抑制人成纤维细胞的SASP[25-26]。<br> 雷帕霉素降低IL-6和其他细胞因子mRNA水平,并选择性地抑制膜结合细胞因子IL-1α的翻译，分泌减少的IL-1α对 NF-κB转录活性刺激也降低，而NF-κB对SASP有着更多的调控作用，这揭示了mTOR抑制剂雷帕霉素的抗衰老作用。<br> 同时，雷帕霉素可以抑制衰老成纤维细胞刺激小鼠前列腺肿瘤生长的能力，因此,雷帕霉素可能通过抑制衰老相关炎症，改善年龄相关的疾病,包括癌症晚期[27, 31]。</p><h2 id="sasp与相关疾病" tabindex="-1"><a class="header-anchor" href="#sasp与相关疾病"><span>SASP与相关疾病</span></a></h2><h3 id="sasp与肿瘤" tabindex="-1"><a class="header-anchor" href="#sasp与肿瘤"><span>SASP与肿瘤</span></a></h3><p>细胞衰老是一个有效的抗癌机制，阻止有丝分裂感受态细胞的增殖，从而防止恶变。</p><h1 id="促衰老疗法最近成为一个治疗癌症的新治疗方法-然而-这一观念与衰老肿瘤细胞的sasp相冲突-因为sasp可以促肿瘤-然而衰老细胞具有抑制肿瘤的效果。" tabindex="-1"><a class="header-anchor" href="#促衰老疗法最近成为一个治疗癌症的新治疗方法-然而-这一观念与衰老肿瘤细胞的sasp相冲突-因为sasp可以促肿瘤-然而衰老细胞具有抑制肿瘤的效果。"><span>促衰老疗法最近成为一个治疗癌症的新治疗方法,然而，这一观念与衰老肿瘤细胞的SASP相冲突，因为SASP可以促肿瘤，然而衰老细胞具有抑制肿瘤的效果。</span></a></h1><h1 id="在pten基因缺失的肿瘤细胞中-激活jak2-stat3通路-建立了免疫抑制肿瘤微环境-导致肿瘤生长和抗药性。" tabindex="-1"><a class="header-anchor" href="#在pten基因缺失的肿瘤细胞中-激活jak2-stat3通路-建立了免疫抑制肿瘤微环境-导致肿瘤生长和抗药性。"><span>在PTEN基因缺失的肿瘤细胞中，激活JAK2/STAT3通路,建立了免疫抑制肿瘤微环境，导致肿瘤生长和抗药性。</span></a></h1><h1 id="通过下调蛋白质酪氨酸磷酸酶ptpn11-shp2-激活pten缺失肿瘤中jak2-stat3信号通路-该激活通路是稳定的-这为存在一个新的pten-shp2轴提供了证据。" tabindex="-1"><a class="header-anchor" href="#通过下调蛋白质酪氨酸磷酸酶ptpn11-shp2-激活pten缺失肿瘤中jak2-stat3信号通路-该激活通路是稳定的-这为存在一个新的pten-shp2轴提供了证据。"><span>通过下调蛋白质酪氨酸磷酸酶PTPN11/SHP2，激活PTEN缺失肿瘤中JAK2/STAT3信号通路，该激活通路是稳定的，这为存在一个新的PTEN/SHP2轴提供了证据。</span></a></h1><h1 id="重要的是-用多烯紫杉醇联合jak2抑制剂作用于pten缺失肿瘤-将改变sasp并提高多烯紫杉醇诱导衰老的效率。" tabindex="-1"><a class="header-anchor" href="#重要的是-用多烯紫杉醇联合jak2抑制剂作用于pten缺失肿瘤-将改变sasp并提高多烯紫杉醇诱导衰老的效率。"><span>重要的是，用多烯紫杉醇联合JAK2抑制剂作用于PTEN缺失肿瘤,将改变SASP并提高多烯紫杉醇诱导衰老的效率。</span></a></h1><h1 id="这些说明衰老肿瘤细胞的免疫监视可以在特殊遗传背景下被抑制-但是也可能被药物治疗所诱发。" tabindex="-1"><a class="header-anchor" href="#这些说明衰老肿瘤细胞的免疫监视可以在特殊遗传背景下被抑制-但是也可能被药物治疗所诱发。"><span>这些说明衰老肿瘤细胞的免疫监视可以在特殊遗传背景下被抑制，但是也可能被药物治疗所诱发。</span></a></h1><h1 id="衰老细胞分泌的蛋白质取决于衰老肿瘤细胞的基因背景。" tabindex="-1"><a class="header-anchor" href="#衰老细胞分泌的蛋白质取决于衰老肿瘤细胞的基因背景。"><span>衰老细胞分泌的蛋白质取决于衰老肿瘤细胞的基因背景。</span></a></h1><h1 id="尽管sasp对肿瘤生物学具有重要的意义-但是它如何调控肿瘤仍然相对不明确。" tabindex="-1"><a class="header-anchor" href="#尽管sasp对肿瘤生物学具有重要的意义-但是它如何调控肿瘤仍然相对不明确。"><span>尽管SASP对肿瘤生物学具有重要的意义,但是它如何调控肿瘤仍然相对不明确。</span></a></h1><h1 id="" tabindex="-1"><a class="header-anchor" href="#"><span></span></a></h1><h1 id="sasp在小鼠肥胖相关肝细胞癌的发展过程中发挥重要的促进作用。" tabindex="-1"><a class="header-anchor" href="#sasp在小鼠肥胖相关肝细胞癌的发展过程中发挥重要的促进作用。"><span>SASP在小鼠肥胖相关肝细胞癌的发展过程中发挥重要的促进作用。</span></a></h1><h1 id="饮食或遗传肥胖导致肠道菌群改变-从而使脱氢胆酸-dca-水平升高-它是一种可以导致dna损伤的肠道细菌代谢物。" tabindex="-1"><a class="header-anchor" href="#饮食或遗传肥胖导致肠道菌群改变-从而使脱氢胆酸-dca-水平升高-它是一种可以导致dna损伤的肠道细菌代谢物。"><span>饮食或遗传肥胖导致肠道菌群改变,从而使脱氢胆酸(DCA)水平升高,它是一种可以导致DNA损伤的肠道细菌代谢物。</span></a></h1><h1 id="dca的肝肠循环引发肝星状细胞-hscs-sasp表型-进而在肝脏中分泌各种炎症和促癌因子-从而促进暴露于化学致癌物的小鼠肝癌的发展。" tabindex="-1"><a class="header-anchor" href="#dca的肝肠循环引发肝星状细胞-hscs-sasp表型-进而在肝脏中分泌各种炎症和促癌因子-从而促进暴露于化学致癌物的小鼠肝癌的发展。"><span>DCA的肝肠循环引发肝星状细胞(HSCs)SASP表型,进而在肝脏中分泌各种炎症和促癌因子,从而促进暴露于化学致癌物的小鼠肝癌的发展。</span></a></h1><h1 id="值得注意的是-阻止dca的产生或减少肠道肥胖老鼠的细菌可有效防止肝癌发展。" tabindex="-1"><a class="header-anchor" href="#值得注意的是-阻止dca的产生或减少肠道肥胖老鼠的细菌可有效防止肝癌发展。"><span>值得注意的是,阻止DCA的产生或减少肠道肥胖老鼠的细菌可有效防止肝癌发展。</span></a></h1><h1 id="当小鼠缺乏一个sasp诱导物或减少衰老肝星状细胞时也观察到类似的结果-这表明dca-sasp轴在肝星状细胞在肥胖相关肝细胞癌发展中有关键作用。" tabindex="-1"><a class="header-anchor" href="#当小鼠缺乏一个sasp诱导物或减少衰老肝星状细胞时也观察到类似的结果-这表明dca-sasp轴在肝星状细胞在肥胖相关肝细胞癌发展中有关键作用。"><span>当小鼠缺乏一个SASP诱导物或减少衰老肝星状细胞时也观察到类似的结果,这表明DCA-SASP轴在肝星状细胞在肥胖相关肝细胞癌发展中有关键作用。</span></a></h1><h1 id="此外-非酒精性脂肪肝的肝癌患者也有sasp的迹象-表示人类肥胖相关肝细胞癌也可能是相同的通路。" tabindex="-1"><a class="header-anchor" href="#此外-非酒精性脂肪肝的肝癌患者也有sasp的迹象-表示人类肥胖相关肝细胞癌也可能是相同的通路。"><span>此外,非酒精性脂肪肝的肝癌患者也有SASP的迹象，表示人类肥胖相关肝细胞癌也可能是相同的通路。</span></a></h1><h1 id="这些研究结果为肥胖相关癌症提供了有价值的新见解-并为如何控制开辟了一个新的可能。" tabindex="-1"><a class="header-anchor" href="#这些研究结果为肥胖相关癌症提供了有价值的新见解-并为如何控制开辟了一个新的可能。"><span>这些研究结果为肥胖相关癌症提供了有价值的新见解，并为如何控制开辟了一个新的可能。</span></a></h1><h3 id="sasp与心血管疾病" tabindex="-1"><a class="header-anchor" href="#sasp与心血管疾病"><span>SASP与心血管疾病</span></a></h3><p>慢性心血管疾病和肾脏疾病会对内皮祖细胞造成伤害而出现早衰和特殊功能衰退。</p><h1 id="sasp的释放会影响邻近细胞-使再生能力进一步恶化-从而加重病情。" tabindex="-1"><a class="header-anchor" href="#sasp的释放会影响邻近细胞-使再生能力进一步恶化-从而加重病情。"><span>SASP的释放会影响邻近细胞,使再生能力进一步恶化，从而加重病情。</span></a></h1><h1 id="正是因为这些原因-超过150例的内皮祖细胞移植正在被不同的心血管疾病临床试验所使用。" tabindex="-1"><a class="header-anchor" href="#正是因为这些原因-超过150例的内皮祖细胞移植正在被不同的心血管疾病临床试验所使用。"><span>正是因为这些原因,超过150例的内皮祖细胞移植正在被不同的心血管疾病临床试验所使用。</span></a></h1><h3 id="sasp与慢性阻塞性肺病-copd" tabindex="-1"><a class="header-anchor" href="#sasp与慢性阻塞性肺病-copd"><span>SASP与慢性阻塞性肺病(COPD)</span></a></h3><p>气道的慢性炎症和肺泡腔以及肺组织破坏是COPD的标志。</p><h1 id="最近研究显示-细胞衰老可能在copd发病机制中发挥作用。" tabindex="-1"><a class="header-anchor" href="#最近研究显示-细胞衰老可能在copd发病机制中发挥作用。"><span>最近研究显示，细胞衰老可能在COPD发病机制中发挥作用。</span></a></h1><h1 id="当衰老诱导dna损伤时-就会出现sasp。" tabindex="-1"><a class="header-anchor" href="#当衰老诱导dna损伤时-就会出现sasp。"><span>当衰老诱导DNA损伤时，就会出现SASP。</span></a></h1><h1 id="sasp可能是慢性炎症的重要驱动力-它会加重copd。" tabindex="-1"><a class="header-anchor" href="#sasp可能是慢性炎症的重要驱动力-它会加重copd。"><span>SASP可能是慢性炎症的重要驱动力，它会加重COPD。</span></a></h1><h3 id="sasp与骨关节炎" tabindex="-1"><a class="header-anchor" href="#sasp与骨关节炎"><span>SASP与骨关节炎</span></a></h3><p>衰老是骨关节炎(OA)发展的一个重要因素,机制是多方面的,&quot;炎性衰老&quot;可能是机制之一。</p><h1 id="年龄相关炎症可以是系统性的-也可以是局部性的。" tabindex="-1"><a class="header-anchor" href="#年龄相关炎症可以是系统性的-也可以是局部性的。"><span>年龄相关炎症可以是系统性的，也可以是局部性的。</span></a></h1><h1 id="脂肪组织的衰老变化可以促进系统性炎症-可促进il-6和tnf-α等细胞因子的增加-而il-6是sasp重要组成成分。" tabindex="-1"><a class="header-anchor" href="#脂肪组织的衰老变化可以促进系统性炎症-可促进il-6和tnf-α等细胞因子的增加-而il-6是sasp重要组成成分。"><span>脂肪组织的衰老变化可以促进系统性炎症，可促进IL-6和TNF-α等细胞因子的增加，而IL-6是SASP重要组成成分。</span></a></h1><h1 id="众多研究显示随着年龄增加-血液中il-6水平也随之增加-高水平的il-6将增加膝骨关节炎的患病风险。" tabindex="-1"><a class="header-anchor" href="#众多研究显示随着年龄增加-血液中il-6水平也随之增加-高水平的il-6将增加膝骨关节炎的患病风险。"><span>众多研究显示随着年龄增加，血液中IL-6水平也随之增加,高水平的IL-6将增加膝骨关节炎的患病风险。</span></a></h1><h1 id="连接骨组织的细胞-包括软骨细胞和半月板细胞-以及膝关节邻近的髌下脂肪-都可能随着年龄增加而导致骨关节炎。" tabindex="-1"><a class="header-anchor" href="#连接骨组织的细胞-包括软骨细胞和半月板细胞-以及膝关节邻近的髌下脂肪-都可能随着年龄增加而导致骨关节炎。"><span>连接骨组织的细胞,包括软骨细胞和半月板细胞,以及膝关节邻近的髌下脂肪,都可能随着年龄增加而导致骨关节炎。</span></a></h1><h1 id="增加的促炎介质-包括细胞因子、趋化因子以及基质降解酶-在联合组织损坏过程中也起了重要的作用-这都是细胞衰老和sasp的结果。" tabindex="-1"><a class="header-anchor" href="#增加的促炎介质-包括细胞因子、趋化因子以及基质降解酶-在联合组织损坏过程中也起了重要的作用-这都是细胞衰老和sasp的结果。"><span>增加的促炎介质(包括细胞因子、趋化因子以及基质降解酶)在联合组织损坏过程中也起了重要的作用,这都是细胞衰老和SASP的结果。</span></a></h1><h1 id="需要进行进一步的研究以便更好地了解炎性衰老在骨关节炎中所扮演的角色-这样就可以制定针对炎症新的干预措施-不仅可以减少骨联合组织的破坏-而且可以减轻老年骨关节炎患者的疼痛和残疾状况。" tabindex="-1"><a class="header-anchor" href="#需要进行进一步的研究以便更好地了解炎性衰老在骨关节炎中所扮演的角色-这样就可以制定针对炎症新的干预措施-不仅可以减少骨联合组织的破坏-而且可以减轻老年骨关节炎患者的疼痛和残疾状况。"><span>需要进行进一步的研究以便更好地了解炎性衰老在骨关节炎中所扮演的角色,这样就可以制定针对炎症新的干预措施，不仅可以减少骨联合组织的破坏,而且可以减轻老年骨关节炎患者的疼痛和残疾状况。</span></a></h1><h3 id="sasp与糖尿病" tabindex="-1"><a class="header-anchor" href="#sasp与糖尿病"><span>SASP与糖尿病</span></a></h3><p>衰老细胞可能通过直接影响胰岛β细胞、SASP调节组织损伤、参与脂肪组织的功能障碍在2型糖尿病的发病机制中发挥作用。</p><h1 id="反过来-糖尿病中的代谢和信号的变化-例如高流通葡萄糖、脂质代谢的改变和生长激素轴的变动-可以促进衰老细胞的形成。" tabindex="-1"><a class="header-anchor" href="#反过来-糖尿病中的代谢和信号的变化-例如高流通葡萄糖、脂质代谢的改变和生长激素轴的变动-可以促进衰老细胞的形成。"><span>反过来，糖尿病中的代谢和信号的变化，例如高流通葡萄糖、脂质代谢的改变和生长激素轴的变动,可以促进衰老细胞的形成。</span></a></h1><h1 id="衰老细胞和sasp对2型糖尿病及并发症的预防和治疗有着重要的意义。" tabindex="-1"><a class="header-anchor" href="#衰老细胞和sasp对2型糖尿病及并发症的预防和治疗有着重要的意义。"><span>衰老细胞和SASP对2型糖尿病及并发症的预防和治疗有着重要的意义。</span></a></h1><h2 id="衰老相关四高症" tabindex="-1"><a class="header-anchor" href="#衰老相关四高症"><span>衰老相关四高症</span></a></h2><h1 id="四高症-four-hypers-syndrome" tabindex="-1"><a class="header-anchor" href="#四高症-four-hypers-syndrome"><span>四高症(four hypers syndrome)</span></a></h1><p>hyperglycemia, hypertension, hyperlipidemia</p><h3 id="hyperglycemia" tabindex="-1"><a class="header-anchor" href="#hyperglycemia"><span>Hyperglycemia</span></a></h3><p>Abnormally high blood glucose level.</p><h3 id="glucose-intolerance" tabindex="-1"><a class="header-anchor" href="#glucose-intolerance"><span>Glucose Intolerance</span></a></h3><p>A pathological state in which blood glucose level is less than approximately 140 mg/100 ml of plasma at fasting, and above approximately 200 mg/100 ml plasma at 30-, 60-, or 90-minute during a glucose tolerance test.</p><h1 id="this-condition-is-seen-frequently-in-diabetes-mellitus-but-also-occurs-with-other-diseases-and-malnutrition" tabindex="-1"><a class="header-anchor" href="#this-condition-is-seen-frequently-in-diabetes-mellitus-but-also-occurs-with-other-diseases-and-malnutrition"><span>This condition is seen frequently in diabetes mellitus, but also occurs with other diseases and malnutrition.</span></a></h1><h3 id="hyperglykemi" tabindex="-1"><a class="header-anchor" href="#hyperglykemi"><span>Hyperglykemi</span></a></h3><p>Onormalt höga blodsockernivåer.</p><h3 id="glukosintolerans" tabindex="-1"><a class="header-anchor" href="#glukosintolerans"><span>Glukosintolerans</span></a></h3><p>Ett sjukligt tillstånd, där blodglukosnivån är under 140 mg/100 ml plasma vid fasta, och över 200 mg/100 ml plasma vid 30-, 60och 90-minutersintervall vid glukostoleranstest.</p><h1 id="tillstandet-ar-vanligt-vid-diabetes-mellitus-men-kan-aven-forekomma-i-samband-med-andra-sjukdomar-och-undernaring" tabindex="-1"><a class="header-anchor" href="#tillstandet-ar-vanligt-vid-diabetes-mellitus-men-kan-aven-forekomma-i-samband-med-andra-sjukdomar-och-undernaring"><span>Tillståndet är vanligt vid diabetes mellitus, men kan även förekomma i samband med andra sjukdomar och undernäring.</span></a></h1><h3 id="hyperuricemia" tabindex="-1"><a class="header-anchor" href="#hyperuricemia"><span>Hyperuricemia</span></a></h3><p>Excessive uric acid or urate in blood as defined by its solubility in plasma at 37 degrees c;</p><h1 id="greater-than-0-42mmol-per-liter-7-0mg-dl-in-men-or-0-36mmol-per-liter-6-0mg-dl-in-women" tabindex="-1"><a class="header-anchor" href="#greater-than-0-42mmol-per-liter-7-0mg-dl-in-men-or-0-36mmol-per-liter-6-0mg-dl-in-women"><span>greater than 0.42mmol per liter (7.0mg/dl) in men or 0.36mmol per liter (6.0mg/dL) in women.</span></a></h1><h1 id="this-condition-is-caused-by-overproduction-of-uric-acid-or-impaired-renal-clearance" tabindex="-1"><a class="header-anchor" href="#this-condition-is-caused-by-overproduction-of-uric-acid-or-impaired-renal-clearance"><span>This condition is caused by overproduction of uric acid or impaired renal clearance.</span></a></h1><h1 id="hyperuricemia-can-be-acquired-drug-induced-or-genetically-determined-lesch-nyhan-syndrome" tabindex="-1"><a class="header-anchor" href="#hyperuricemia-can-be-acquired-drug-induced-or-genetically-determined-lesch-nyhan-syndrome"><span>Hyperuricemia can be acquired, drug-induced or genetically determined (lesch-nyhan syndrome).</span></a></h1><h1 id="it-is-associated-with-hypertension-and-gout" tabindex="-1"><a class="header-anchor" href="#it-is-associated-with-hypertension-and-gout"><span>It is associated with hypertension and gout.</span></a></h1><h3 id="hyperurikemi" tabindex="-1"><a class="header-anchor" href="#hyperurikemi"><span>Hyperurikemi</span></a></h3><p>För höga halter av urinsyra eller urat i blodet, i förhållande till deras löslighet i plasma vid 37 grader; gränsen går vid 0,42 mmol/l (0,7 mg/dl) hos män och 0,36 mmol/l (6,0 mg/dl) hos kvinnor. Tillståndet beror på överproduktion av urinsyra eller defekt njureliminering. Hyperurikemi kan vara förvärvad, läkemedelsframkallad eller genetiskt betingad (Lesch-Nyhans syndrom). Tillståndet är förenat med högt blodtryck och gikt.</p><h3 id="hypertension" tabindex="-1"><a class="header-anchor" href="#hypertension"><span>Hypertension</span></a></h3><p>Persistently high systemic arterial blood pressure.<br> Based on multiple readings (blood pressure determination), hypertension is currently defined as when systolic pressure is consistently greater than 140 mm Hg or when diastolic pressure is consistently 90 mm Hg or more.</p><h3 id="hogt-blodtryck" tabindex="-1"><a class="header-anchor" href="#hogt-blodtryck"><span>Högt blodtryck</span></a></h3><p>Ihållande, högt blodtryck i artärsystemet.<br> Utifrån flera mätningar (blodtrycksbestämning) definieras högt blodtryck som ett tillstånd då det systoliska trycket konstant är högre än 140 mm Hg eller då det diastoliska trycket konstant är högre än 90 mm Hg.</p><h1 id="流行病学" tabindex="-1"><a class="header-anchor" href="#流行病学"><span>流行病学</span></a></h1><p>根据2019年《柳叶刀》的流行病学调查，<br> 慢性疾病如中风、缺血性心脏病以及肺癌，现已成为中国人群过早死亡的主要原因。<br> 在全国范围内，吸烟在21个省份中位列首要危险因素，在其余省份中也排名第二或第三。</p><h1 id="_10-1016-s0140-6736-19-30427-1" tabindex="-1"><a class="header-anchor" href="#_10-1016-s0140-6736-19-30427-1"><span>(10.1016/S0140-6736(19)30427-1)</span></a></h1><p>一些危险因素暴露正在上升，特别是高血糖、高血压、高体质指数(BMI)、以及在许多省份的室外空气污染。<br> 男性高血压检出率高于女性，且所有年龄组男性检出率均高于女性，男、女性高血压检出率随年龄增长而增加。<br> 男性高血压发病率高于女性，可能与男性抽烟、饮酒及饮食不规律等因素有关。</p><h3 id="膳食风险因素" tabindex="-1"><a class="header-anchor" href="#膳食风险因素"><span>膳食风险因素</span></a></h3><p>根据由中国营养学会组织编写的《中国居民膳食指南科学研究报告(2021)》，</p><h1 id="与主要健康结局风险降低相关联的膳食因素包括全谷物、蔬菜、水果、大豆及其制品、奶类及其制品、鱼肉、坚果、饮水-饮茶-等。" tabindex="-1"><a class="header-anchor" href="#与主要健康结局风险降低相关联的膳食因素包括全谷物、蔬菜、水果、大豆及其制品、奶类及其制品、鱼肉、坚果、饮水-饮茶-等。"><span>与主要健康结局风险降低相关联的膳食因素包括全谷物、蔬菜、水果、大豆及其制品、奶类及其制品、鱼肉、坚果、饮水(饮茶)等。</span></a></h1><h1 id="过多摄入可增加不良健康结局风险的膳食因素则包括畜肉、烟熏肉、食盐、饮酒、含糖饮料、油脂等。" tabindex="-1"><a class="header-anchor" href="#过多摄入可增加不良健康结局风险的膳食因素则包括畜肉、烟熏肉、食盐、饮酒、含糖饮料、油脂等。"><span>过多摄入可增加不良健康结局风险的膳食因素则包括畜肉、烟熏肉、食盐、饮酒、含糖饮料、油脂等。</span></a></h1><h1 id="-1" tabindex="-1"><a class="header-anchor" href="#-1"><span></span></a></h1><p>长期遵循平衡膳食模式，是健康长寿和预防膳食相关慢性病的重要基石，并可降低全因死亡风险。</p><h1 id="中国人群不同膳食模式对健康结局的影响研究结果显示-以多蔬菜水果、多鱼虾水产品、经常吃奶类和大豆制品、适量的谷类和肉禽类、烹调清淡少盐为主要特点的江南地区模式-代表了东方健康膳食模式。" tabindex="-1"><a class="header-anchor" href="#中国人群不同膳食模式对健康结局的影响研究结果显示-以多蔬菜水果、多鱼虾水产品、经常吃奶类和大豆制品、适量的谷类和肉禽类、烹调清淡少盐为主要特点的江南地区模式-代表了东方健康膳食模式。"><span>中国人群不同膳食模式对健康结局的影响研究结果显示，以多蔬菜水果、多鱼虾水产品、经常吃奶类和大豆制品、适量的谷类和肉禽类、烹调清淡少盐为主要特点的江南地区模式，代表了东方健康膳食模式。</span></a></h1><h1 id="具有这些膳食特点的地区-人群发生超重肥胖、2型糖尿病、代谢综合征和脑卒中等疾病的风险均较低。" tabindex="-1"><a class="header-anchor" href="#具有这些膳食特点的地区-人群发生超重肥胖、2型糖尿病、代谢综合征和脑卒中等疾病的风险均较低。"><span>具有这些膳食特点的地区，人群发生超重肥胖、2型糖尿病、代谢综合征和脑卒中等疾病的风险均较低。</span></a></h1><p>(10.1016/S2213-8587(19)30152-4)</p><h1 id="病理生理学" tabindex="-1"><a class="header-anchor" href="#病理生理学"><span>病理生理学</span></a></h1><h2 id="高血压-hypertension" tabindex="-1"><a class="header-anchor" href="#高血压-hypertension"><span>高血压(hypertension)</span></a></h2><p>(高血压的介绍和流行病学)</p><h1 id="高血压不仅为最常见的心血管疾病之一-更是各种冠心病和脑卒中等心脑血管疾病的重要危险因素。" tabindex="-1"><a class="header-anchor" href="#高血压不仅为最常见的心血管疾病之一-更是各种冠心病和脑卒中等心脑血管疾病的重要危险因素。"><span>高血压不仅为最常见的心血管疾病之一，更是各种冠心病和脑卒中等心脑血管疾病的重要危险因素。</span></a></h1><p>遗传因素、高盐饮食、饮酒、超重和吸烟都是高血压的危险因素。</p><h1 id="-2" tabindex="-1"><a class="header-anchor" href="#-2"><span></span></a></h1><ul><li>高血压发病隐匿，且易引发各种冠心病及脑卒中等心脑血管疾病，其所致心脑血管疾病并发症病死率位居首位。</li></ul><h1 id="高血糖、高尿酸血症及血脂异常人群的高血压检出率均高于正常人群-且差异有统计学意义。" tabindex="-1"><a class="header-anchor" href="#高血糖、高尿酸血症及血脂异常人群的高血压检出率均高于正常人群-且差异有统计学意义。"><span>高血糖、高尿酸血症及血脂异常人群的高血压检出率均高于正常人群，且差异有统计学意义。</span></a></h1><h1 id="预防高血压的发生发展-除关注高盐饮食、饮酒、超重和吸烟等可防可控的危险因素外-还应积极监测血糖水平、血尿酸水平和血脂情况-早发现、早干预治疗。" tabindex="-1"><a class="header-anchor" href="#预防高血压的发生发展-除关注高盐饮食、饮酒、超重和吸烟等可防可控的危险因素外-还应积极监测血糖水平、血尿酸水平和血脂情况-早发现、早干预治疗。"><span>预防高血压的发生发展，除关注高盐饮食、饮酒、超重和吸烟等可防可控的危险因素外，还应积极监测血糖水平、血尿酸水平和血脂情况，早发现、早干预治疗。</span></a></h1><h1 id="未控制的高血压可促进动脉粥样硬化的进展-导致靶器官损害-甚至严重的并发症-例如-脑卒中、心脏病、肾脏病、外周血管疾病和眼底疾病等。" tabindex="-1"><a class="header-anchor" href="#未控制的高血压可促进动脉粥样硬化的进展-导致靶器官损害-甚至严重的并发症-例如-脑卒中、心脏病、肾脏病、外周血管疾病和眼底疾病等。"><span>未控制的高血压可促进动脉粥样硬化的进展，导致靶器官损害，甚至严重的并发症，例如：脑卒中、心脏病、肾脏病、外周血管疾病和眼底疾病等。</span></a></h1><p>难治性高血压的病因及病理生理学机制复杂多样，是在神经、体液和内分泌等多种因素单独或共同作用下产生的。<br> 高盐饮食、吸烟嗜酒、超重和肥胖、颈动脉压力反射功能减退和交感神经兴奋是高血压患者血压难以控制的基本和重要原因。</p><h1 id="循环和组织中的肾素血管紧张素醛固酮系统-renin-angiolensin-aldosteronesystem-raas-的激活以及中枢或局部组织-特别是肾脏交感神经活性的过度增高会启动氧化应激过程和炎症因子从而加速动脉硬化的发生和进展-加重血管结构和功能的异常-进而使增高的血压难以获得控制。" tabindex="-1"><a class="header-anchor" href="#循环和组织中的肾素血管紧张素醛固酮系统-renin-angiolensin-aldosteronesystem-raas-的激活以及中枢或局部组织-特别是肾脏交感神经活性的过度增高会启动氧化应激过程和炎症因子从而加速动脉硬化的发生和进展-加重血管结构和功能的异常-进而使增高的血压难以获得控制。"><span>循环和组织中的肾素血管紧张素醛固酮系统(renin-angiolensin-aldosteronesystem , RAAS )的激活以及中枢或局部组织，特别是肾脏交感神经活性的过度增高会启动氧化应激过程和炎症因子从而加速动脉硬化的发生和进展，加重血管结构和功能的异常，进而使增高的血压难以获得控制。</span></a></h1><h1 id="交感神经以及raas活性增强及持续存在是其另一发病机制-多重因素共同影响交感神经及raas激活-如胰岛素抵抗、脂肪细胞因子、内皮细胞功能障碍、间歇性低氧血症、体内容量负荷过高、醛固酮等作用于中枢神经系统以及动脉化学感受器和压力感受器的功能失调等。" tabindex="-1"><a class="header-anchor" href="#交感神经以及raas活性增强及持续存在是其另一发病机制-多重因素共同影响交感神经及raas激活-如胰岛素抵抗、脂肪细胞因子、内皮细胞功能障碍、间歇性低氧血症、体内容量负荷过高、醛固酮等作用于中枢神经系统以及动脉化学感受器和压力感受器的功能失调等。"><span>交感神经以及RAAS活性增强及持续存在是其另一发病机制，多重因素共同影响交感神经及RAAS激活，如胰岛素抵抗、脂肪细胞因子、内皮细胞功能障碍、间歇性低氧血症、体内容量负荷过高、醛固酮等作用于中枢神经系统以及动脉化学感受器和压力感受器的功能失调等。</span></a></h1><h1 id="另外" tabindex="-1"><a class="header-anchor" href="#另外"><span>另外，</span></a></h1><ul><li>抗AT1受体自身抗体的存在是导致难治性高血压的重要因素，因为抗AT1受体自身抗体可模拟血管紧张素而激动血管紧张素受体，引起血压升高；同时，由于常规的降压药物不能阻断这种抗体的作用，而影响了高血压的治疗。<br> 肾脏在难治性高血压的发病过程中也具有重要作用，其中，肾脏局部交感神经过度激活是其发病基础以及重要的病理生理学机制之一。</li></ul><h1 id="肾交感神经分为传入神经和传出神经-其中传出神经的激活产生和分泌去甲肾上腺素。" tabindex="-1"><a class="header-anchor" href="#肾交感神经分为传入神经和传出神经-其中传出神经的激活产生和分泌去甲肾上腺素。"><span>肾交感神经分为传入神经和传出神经，其中传出神经的激活产生和分泌去甲肾上腺素。</span></a></h1><h1 id="去甲肾上腺素水平升高是肾交感神经活性增高的标志-使水钠重吸收增加、肾血管收缩从而使肾血流量减少-同时它还激活醛固酮系统增加肾素分泌而升高血压-而传入神经的过度兴奋可激活中枢神经系统-从而分泌加压素而升高血压。" tabindex="-1"><a class="header-anchor" href="#去甲肾上腺素水平升高是肾交感神经活性增高的标志-使水钠重吸收增加、肾血管收缩从而使肾血流量减少-同时它还激活醛固酮系统增加肾素分泌而升高血压-而传入神经的过度兴奋可激活中枢神经系统-从而分泌加压素而升高血压。"><span>去甲肾上腺素水平升高是肾交感神经活性增高的标志，使水钠重吸收增加、肾血管收缩从而使肾血流量减少，同时它还激活醛固酮系统增加肾素分泌而升高血压，而传入神经的过度兴奋可激活中枢神经系统，从而分泌加压素而升高血压。</span></a></h1><h1 id="交感神经切除或交感神经阻滞剂作用于肾缺血-再灌注后的动物模型可使其去甲肾上腺素分泌量明显下降-进而有效地控制血压-反之-血压难以控制。" tabindex="-1"><a class="header-anchor" href="#交感神经切除或交感神经阻滞剂作用于肾缺血-再灌注后的动物模型可使其去甲肾上腺素分泌量明显下降-进而有效地控制血压-反之-血压难以控制。"><span>交感神经切除或交感神经阻滞剂作用于肾缺血/再灌注后的动物模型可使其去甲肾上腺素分泌量明显下降，进而有效地控制血压，反之，血压难以控制。</span></a></h1><p>空腹血糖(fasting plasma glucose,FPG)、血尿酸(uric acid,UA)、低密度脂蛋白胆固醇(low-density lipoprotein cholesterol,LDL-C)、</p><h1 id="和三酰甘油-triglyceride-tg" tabindex="-1"><a class="header-anchor" href="#和三酰甘油-triglyceride-tg"><span>和三酰甘油(triglyceride,TG)</span></a></h1><p>是高血压的独立危险因素。<br> 高血糖、高尿酸血症、血脂异常与高血压存在一定的相关性，是高血压的危险因素。</p><h1 id="_10-19790-j-cnki-jcm-2020-22-04" tabindex="-1"><a class="header-anchor" href="#_10-19790-j-cnki-jcm-2020-22-04"><span>(10.19790/j.cnki.JCM.2020.22.04)</span></a></h1><h2 id="高血脂-hyperlipidemia" tabindex="-1"><a class="header-anchor" href="#高血脂-hyperlipidemia"><span>高血脂(hyperlipidemia)</span></a></h2><p>血脂代谢紊乱后，血脂水平升高，血管内血小板凝聚增加，对血管内皮结构造成损害，进而导致血液黏滞性上升。<br> 高血脂可黏附在血管内壁上，导致动脉粥样硬化，进而使血管狭窄，造成血压上升。</p><h2 id="高血糖-hyperglycemia" tabindex="-1"><a class="header-anchor" href="#高血糖-hyperglycemia"><span>高血糖(hyperglycemia)</span></a></h2><h1 id="_2型糖尿病患者的血尿酸水平与血糖、血脂水平具有一定相关性-血尿酸水平升高是诱发糖脂代谢紊乱的危险因素。" tabindex="-1"><a class="header-anchor" href="#_2型糖尿病患者的血尿酸水平与血糖、血脂水平具有一定相关性-血尿酸水平升高是诱发糖脂代谢紊乱的危险因素。"><span>2型糖尿病患者的血尿酸水平与血糖、血脂水平具有一定相关性，血尿酸水平升高是诱发糖脂代谢紊乱的危险因素。</span></a></h1><p>高糖饮食可能为高尿酸血症和高血压发病中介。<br> 2型糖尿病患者体内3-磷酸甘油醛脱氢酶的活性下降，导致糖酵解中间产物向5-磷酸核糖及磷酸核糖焦磷酸转移，尿酸生成增多进而引发高尿酸血症<br> 高GLU可促使机体进行大量脂肪动员，引发血脂代谢异常，减少脂肪合成代谢，降低脂肪组织清除血清蛋白中TG和脂肪酸的能力，升高血液中TG浓度，从而导致高脂血症。</p><h2 id="高尿酸-hyperuricemia" tabindex="-1"><a class="header-anchor" href="#高尿酸-hyperuricemia"><span>高尿酸(hyperuricemia)</span></a></h2><p>血尿酸水平与HbA 1c、FBG、TC、TG和LDL-C水平呈正相关，与HDL-C水平呈负相关。</p><h1 id="高尿酸血症与高血压密切相关-且为高血压的独立危险因素" tabindex="-1"><a class="header-anchor" href="#高尿酸血症与高血压密切相关-且为高血压的独立危险因素"><span>高尿酸血症与高血压密切相关，且为高血压的独立危险因素</span></a></h1><ul><li>UA每升高59.5μmol/L，高血压发生风险上升23%。<br> 人体内尿酸主要来源于嘌呤在肝脏中的氧化，是体内嘌呤代谢的终产物。</li></ul><h1 id="而嘌呤主要来源于体内老旧细胞和动物内脏及海鲜等富含嘌呤食物的核酸氧化分解产物。" tabindex="-1"><a class="header-anchor" href="#而嘌呤主要来源于体内老旧细胞和动物内脏及海鲜等富含嘌呤食物的核酸氧化分解产物。"><span>而嘌呤主要来源于体内老旧细胞和动物内脏及海鲜等富含嘌呤食物的核酸氧化分解产物。</span></a></h1><h1 id="正常情况下-人体内尿酸每日生成与排泄均约600mg-维持体内约1-200mg尿酸水平的动态平衡。" tabindex="-1"><a class="header-anchor" href="#正常情况下-人体内尿酸每日生成与排泄均约600mg-维持体内约1-200mg尿酸水平的动态平衡。"><span>正常情况下，人体内尿酸每日生成与排泄均约600mg，维持体内约1 200mg尿酸水平的动态平衡。</span></a></h1><h1 id="当尿酸生成增多或排泄减少时-均会引起血尿酸水平上升-从而引发一系列生理病理过程。" tabindex="-1"><a class="header-anchor" href="#当尿酸生成增多或排泄减少时-均会引起血尿酸水平上升-从而引发一系列生理病理过程。"><span>当尿酸生成增多或排泄减少时，均会引起血尿酸水平上升，从而引发一系列生理病理过程。</span></a></h1><h1 id="高血尿酸水平可刺激肾素分泌-从而激活肾素-血管紧张素释放系统进而引发高血压" tabindex="-1"><a class="header-anchor" href="#高血尿酸水平可刺激肾素分泌-从而激活肾素-血管紧张素释放系统进而引发高血压"><span>高血尿酸水平可刺激肾素分泌，从而激活肾素-血管紧张素释放系统进而引发高血压；</span></a></h1><h1 id="同时-血管内易析出尿酸盐微结晶。" tabindex="-1"><a class="header-anchor" href="#同时-血管内易析出尿酸盐微结晶。"><span>同时，血管内易析出尿酸盐微结晶。</span></a></h1><h1 id="尿酸盐微结晶沉积于血管壁后直接对血管内膜造成损伤-形成炎症反应导致血小板黏附聚集-促进形成动脉粥样硬化。" tabindex="-1"><a class="header-anchor" href="#尿酸盐微结晶沉积于血管壁后直接对血管内膜造成损伤-形成炎症反应导致血小板黏附聚集-促进形成动脉粥样硬化。"><span>尿酸盐微结晶沉积于血管壁后直接对血管内膜造成损伤，形成炎症反应导致血小板黏附聚集，促进形成动脉粥样硬化。</span></a></h1><h1 id="这将进一步增加心脑血管事件发生的可能性。" tabindex="-1"><a class="header-anchor" href="#这将进一步增加心脑血管事件发生的可能性。"><span>这将进一步增加心脑血管事件发生的可能性。</span></a></h1><h1 id="尿酸与血糖两者的代谢均需经过糖酵解途径-途径中关键酶3-磷酸甘油醛脱氢酶受胰岛素调控。" tabindex="-1"><a class="header-anchor" href="#尿酸与血糖两者的代谢均需经过糖酵解途径-途径中关键酶3-磷酸甘油醛脱氢酶受胰岛素调控。"><span>尿酸与血糖两者的代谢均需经过糖酵解途径，途径中关键酶3-磷酸甘油醛脱氢酶受胰岛素调控。</span></a></h1><p>高尿酸可以促进低密度脂蛋白胆固醇氧化和脂质的过氧化，使内皮细胞功能失调；可以促进血小板聚集从而促进血栓形成。<br> 我国约有高尿酸者1.2亿，男性高发年龄为50~59岁，女性多发于绝经后。<br> 80和90年代我国部分地区高尿酸的流行病学数据显示，10年期间我国高尿酸患病率增加近10倍，并呈逐年升高的趋势，已对人们的健康造成严重的威胁。<br> 体内的老旧细胞，还有食物，尤其是富含嘌呤的食物(如动物内脏、海鲜等)在新陈代谢过程中，其核酸氧化分解产物就有嘌呤(这种内源性的嘌呤占总嘌呤的80%)。<br> 体内产生嘌呤后，会在肝脏中再次氧化为(2,6,8--三氧嘌呤)又称为尿酸。</p><h1 id="正常情况下-体内的尿酸约1-200-mg-每日新生成约600毫克-同时排泄掉600毫克-处于平衡状态。" tabindex="-1"><a class="header-anchor" href="#正常情况下-体内的尿酸约1-200-mg-每日新生成约600毫克-同时排泄掉600毫克-处于平衡状态。"><span>正常情况下，体内的尿酸约1 200 mg，每日新生成约600毫克，同时排泄掉600毫克，处于平衡状态。</span></a></h1><h1 id="如果体内产生过多来不及排泄或者尿酸排泄机制退化-体内尿酸潴留过多-当血液尿酸浓度-7-mg-dl时-会影响人体细胞的正常功能。" tabindex="-1"><a class="header-anchor" href="#如果体内产生过多来不及排泄或者尿酸排泄机制退化-体内尿酸潴留过多-当血液尿酸浓度-7-mg-dl时-会影响人体细胞的正常功能。"><span>如果体内产生过多来不及排泄或者尿酸排泄机制退化，体内尿酸潴留过多，当血液尿酸浓度&gt;7 mg/dl时，会影响人体细胞的正常功能。</span></a></h1><h1 id="长期嘌呤代谢紊乱-血中尿酸过高-尿酸盐结晶沉积在关节的滑膜、滑囊软骨及其他组织中-会引起痛风-表现为反复发作的小关节肿痛。" tabindex="-1"><a class="header-anchor" href="#长期嘌呤代谢紊乱-血中尿酸过高-尿酸盐结晶沉积在关节的滑膜、滑囊软骨及其他组织中-会引起痛风-表现为反复发作的小关节肿痛。"><span>长期嘌呤代谢紊乱，血中尿酸过高，尿酸盐结晶沉积在关节的滑膜、滑囊软骨及其他组织中，会引起痛风，表现为反复发作的小关节肿痛。</span></a></h1><h1 id="当患者长期食用含有嘌呤类的食物如动物内脏、肉类以及海鲜等-均会升高血尿酸-加重病情。" tabindex="-1"><a class="header-anchor" href="#当患者长期食用含有嘌呤类的食物如动物内脏、肉类以及海鲜等-均会升高血尿酸-加重病情。"><span>当患者长期食用含有嘌呤类的食物如动物内脏、肉类以及海鲜等，均会升高血尿酸，加重病情。</span></a></h1><h1 id="如患者伴有某种慢性疾病、长期服用部分药物-如阿司匹林、噻嗪类利尿剂等-也会使得血尿酸的浓度升高。" tabindex="-1"><a class="header-anchor" href="#如患者伴有某种慢性疾病、长期服用部分药物-如阿司匹林、噻嗪类利尿剂等-也会使得血尿酸的浓度升高。"><span>如患者伴有某种慢性疾病、长期服用部分药物(如阿司匹林、噻嗪类利尿剂等)也会使得血尿酸的浓度升高。</span></a></h1><p>高尿酸血症患者发生心脑血管疾病的风险显著高于血尿酸正常者，应加强高尿酸血症患者性别、BMI、Cr、TG等指标的监测，及早诊断和治疗，以预防和降低心脑血管疾病的发生概率。</p><h2 id="糖尿病肾病综合症" tabindex="-1"><a class="header-anchor" href="#糖尿病肾病综合症"><span>糖尿病肾病综合症</span></a></h2><h2 id="心脑血管疾病" tabindex="-1"><a class="header-anchor" href="#心脑血管疾病"><span>心脑血管疾病</span></a></h2><p>心脑血管疾病在临床较为常见，对患者的生命造成严重威胁。<br> 其好发人群为老年人，这与老年人的体质较弱，各器官功能处于衰退阶段，容易引起并发症有关。<br> 心脑血管疾病易患因素可能为：</p><h1 id="_1-血管类因素-如动脉炎、动脉粥样硬化等" tabindex="-1"><a class="header-anchor" href="#_1-血管类因素-如动脉炎、动脉粥样硬化等"><span>(1)血管类因素，如动脉炎、动脉粥样硬化等；</span></a></h1><h1 id="_2-血流动力学因素-如高血压病等" tabindex="-1"><a class="header-anchor" href="#_2-血流动力学因素-如高血压病等"><span>(2)血流动力学因素，如高血压病等；</span></a></h1><h1 id="_3-血液成分因素-如血小板计数升高、白血病以及贫血等" tabindex="-1"><a class="header-anchor" href="#_3-血液成分因素-如血小板计数升高、白血病以及贫血等"><span>(3)血液成分因素，如血小板计数升高、白血病以及贫血等；</span></a></h1><h1 id="_4-血液流变学异常-如糖尿病、高脂血症等" tabindex="-1"><a class="header-anchor" href="#_4-血液流变学异常-如糖尿病、高脂血症等"><span>(4)血液流变学异常，如糖尿病、高脂血症等；</span></a></h1><h1 id="_5-其他-如血液黏稠、过度抽烟酗酒等。" tabindex="-1"><a class="header-anchor" href="#_5-其他-如血液黏稠、过度抽烟酗酒等。"><span>(5)其他，如血液黏稠、过度抽烟酗酒等。</span></a></h1><h1 id="羟基维生素d对糖尿病的影响" tabindex="-1"><a class="header-anchor" href="#羟基维生素d对糖尿病的影响"><span>羟基维生素D对糖尿病的影响</span></a></h1><p>低水平的25(OH)D会增加代谢综合征和胰岛素抵抗发生的风险。<br> T2DM发病的两个关键因素是胰岛素抵抗和胰岛素分泌不足，<br> 维生素D在T2DM发病的两个机制中都起到了一定的作用：</p><ul><li>经过活化的维生素D3与胰腺上的维生素D受体以及钙结合蛋白结合，可促进钙离子内流增加，启动了胰岛素的信号转导，从而促进了胰岛素的分泌；</li><li>被活化的维生素D3同时参与细胞免疫抑制，从而保护胰岛β细胞免受这些细胞因子介导的免疫损伤，减少β细胞的凋亡；</li><li>被活化的维生素D3一方面通过抑制过氧化物酶体增殖物活化受体γ的表达来减少胰岛素抵抗，另一方面可直接激活过氧化物酶体增殖物活化受体δ,调控脂肪酸的代谢，达到改善胰岛素抵抗的作用。</li></ul><h1 id="曾春平及其同事研究了25-oh-d和血清生化指标的相关性-包括" tabindex="-1"><a class="header-anchor" href="#曾春平及其同事研究了25-oh-d和血清生化指标的相关性-包括"><span>曾春平及其同事研究了25(OH)D和血清生化指标的相关性，包括：</span></a></h1><p>糖化血红蛋白(HbA1C)、</p><ul><li>血清总胆固醇(TC)、三酰甘油(TG)、高密度脂蛋白胆固醇(HDL-C)、低密度脂蛋白胆固醇(LDL-C)、空腹葡萄糖(FBG)、肌酐(Crea)、钙(Ca)和磷(P)。<br> T2DM患者血清25(OH)D水平与HbA1C、FBG呈负相关，<br> 与TC、LDL-C、Ca呈正相关，<br> 与TG、HDL-C、P、Crea无明显相关性。</li></ul><h1 id="维生素d3可通过上调维生素dr水平增强自噬活性实现对糖尿病肾病足细胞损伤的抑制作用-进而减少蛋白尿-延缓糖尿病肾病的发展。" tabindex="-1"><a class="header-anchor" href="#维生素d3可通过上调维生素dr水平增强自噬活性实现对糖尿病肾病足细胞损伤的抑制作用-进而减少蛋白尿-延缓糖尿病肾病的发展。"><span>维生素D3可通过上调维生素DR水平增强自噬活性实现对糖尿病肾病足细胞损伤的抑制作用，进而减少蛋白尿，延缓糖尿病肾病的发展。</span></a></h1><h1 id="个体化健康管理-1" tabindex="-1"><a class="header-anchor" href="#个体化健康管理-1"><span>个体化健康管理</span></a></h1><p>个体化健康管理是以每个患者的信息为基础决定治疗方针，从基因组成或表达变化的差异来把握治疗效果或毒副作用等应答，给与每个患者最适宜的药物或疗法。<br> 一些检测项目可以较好地对衰老相关四高症进行表征。</p><h2 id="食物不耐受检测" tabindex="-1"><a class="header-anchor" href="#食物不耐受检测"><span>食物不耐受检测</span></a></h2><p>某些食物的长期摄入可能导致人体不适；</p><h1 id="由食物特异性igg抗体介导的延迟性免疫反应" tabindex="-1"><a class="header-anchor" href="#由食物特异性igg抗体介导的延迟性免疫反应"><span>由食物特异性IgG抗体介导的延迟性免疫反应；</span></a></h1><h1 id="某些人群体内缺乏相应的消化酶-食物以多肽或其它分子形式进入肠道" tabindex="-1"><a class="header-anchor" href="#某些人群体内缺乏相应的消化酶-食物以多肽或其它分子形式进入肠道"><span>某些人群体内缺乏相应的消化酶，食物以多肽或其它分子形式进入肠道；</span></a></h1><h1 id="产生食物特异性igg抗体" tabindex="-1"><a class="header-anchor" href="#产生食物特异性igg抗体"><span>产生食物特异性IgG抗体；</span></a></h1><h1 id="igg抗体与食物分子形成免疫复合物" tabindex="-1"><a class="header-anchor" href="#igg抗体与食物分子形成免疫复合物"><span>IgG抗体与食物分子形成免疫复合物；</span></a></h1><h1 id="胃肠道黏膜淋巴组织将其识别为外来物质-导致免疫反应" tabindex="-1"><a class="header-anchor" href="#胃肠道黏膜淋巴组织将其识别为外来物质-导致免疫反应"><span>胃肠道黏膜淋巴组织将其识别为外来物质，导致免疫反应；</span></a></h1><h1 id="免疫复合物长期积累-导致慢性炎症反应" tabindex="-1"><a class="header-anchor" href="#免疫复合物长期积累-导致慢性炎症反应"><span>免疫复合物长期积累，导致慢性炎症反应；</span></a></h1><p>继而诱发全身各系统的症状或慢性疾病，包括：<br> 肠易激综合症(irritable bowel syndrome, IBS)、<br> 头痛或偏头痛、<br> 疲劳、<br> 和荨麻疹。</p><h1 id="此外" tabindex="-1"><a class="header-anchor" href="#此外"><span>此外，</span></a></h1><ul><li>免疫复合物还可能在肾脏发生堆积并造成伤害，从而影响尿酸的排除，导致血清高尿酸的发生。</li></ul><h3 id="过敏性鼻炎患者食物不耐受的发生率较高" tabindex="-1"><a class="header-anchor" href="#过敏性鼻炎患者食物不耐受的发生率较高"><span>过敏性鼻炎患者食物不耐受的发生率较高</span></a></h3><h1 id="过敏性鼻炎是一种由基因与环境互相作用而诱发的多因素疾病-其发病机制仍未完全清晰" tabindex="-1"><a class="header-anchor" href="#过敏性鼻炎是一种由基因与环境互相作用而诱发的多因素疾病-其发病机制仍未完全清晰"><span>过敏性鼻炎是一种由基因与环境互相作用而诱发的多因素疾病，其发病机制仍未完全清晰；</span></a></h1><h1 id="鼻黏膜非感染性炎性疾病" tabindex="-1"><a class="header-anchor" href="#鼻黏膜非感染性炎性疾病"><span>鼻黏膜非感染性炎性疾病；</span></a></h1><h1 id="特应性个体接触变应原" tabindex="-1"><a class="header-anchor" href="#特应性个体接触变应原"><span>特应性个体接触变应原；</span></a></h1><h1 id="主要由ige介导的介质释放" tabindex="-1"><a class="header-anchor" href="#主要由ige介导的介质释放"><span>主要由IgE介导的介质释放；</span></a></h1><h1 id="有多种免疫活性细胞和细胞因子等参与" tabindex="-1"><a class="header-anchor" href="#有多种免疫活性细胞和细胞因子等参与"><span>有多种免疫活性细胞和细胞因子等参与；</span></a></h1><h1 id="常合并igg以及其他非免疫因素介导的变态反应" tabindex="-1"><a class="header-anchor" href="#常合并igg以及其他非免疫因素介导的变态反应"><span>常合并IgG以及其他非免疫因素介导的变态反应；</span></a></h1><h1 id="过敏性鼻炎合并食物不耐受可使过敏性鼻炎的病情复杂化" tabindex="-1"><a class="header-anchor" href="#过敏性鼻炎合并食物不耐受可使过敏性鼻炎的病情复杂化"><span>过敏性鼻炎合并食物不耐受可使过敏性鼻炎的病情复杂化；</span></a></h1><h2 id="农药残留检测" tabindex="-1"><a class="header-anchor" href="#农药残留检测"><span>农药残留检测</span></a></h2><p>农药残留是使用农药后残存于农产品、生物体及环境中的农药原体、有毒代谢物、降解物和杂质的总称；<br> 有机磷中毒会导致血清胆碱酯酶(CHE)减低；</p><h3 id="农药-肠道-肠道菌群-肥胖通路" tabindex="-1"><a class="header-anchor" href="#农药-肠道-肠道菌群-肥胖通路"><span>农药-肠道/肠道菌群-肥胖通路</span></a></h3><h1 id="通过食物进入消化系统后-首先能够破坏肠道完整性-使得进入血液中内毒素的量增加-引发低度炎症-进而导致胰岛素抗性及肥胖" tabindex="-1"><a class="header-anchor" href="#通过食物进入消化系统后-首先能够破坏肠道完整性-使得进入血液中内毒素的量增加-引发低度炎症-进而导致胰岛素抗性及肥胖"><span>通过食物进入消化系统后，首先能够破坏肠道完整性，使得进入血液中内毒素的量增加，引发低度炎症，进而导致胰岛素抗性及肥胖；</span></a></h1><h1 id="改变肠道中的菌群组成-这种被改变的肠道菌群组成会反作用于宿主-加重机体胰岛素抗性及肥胖的症状。" tabindex="-1"><a class="header-anchor" href="#改变肠道中的菌群组成-这种被改变的肠道菌群组成会反作用于宿主-加重机体胰岛素抗性及肥胖的症状。"><span>改变肠道中的菌群组成，这种被改变的肠道菌群组成会反作用于宿主，加重机体胰岛素抗性及肥胖的症状。</span></a></h1><h2 id="血液内毒素" tabindex="-1"><a class="header-anchor" href="#血液内毒素"><span>血液内毒素</span></a></h2><p>血液内毒素可诱导形成抗体，但是抗体-毒素结合体仍然具有毒性；<br> 能够激活人体内多种免疫细胞；</p><h1 id="例如巨噬细胞" tabindex="-1"><a class="header-anchor" href="#例如巨噬细胞"><span>例如巨噬细胞，</span></a></h1><h1 id="这些免疫细胞随后会产生白介素和肿瘤坏死因子等细胞因子" tabindex="-1"><a class="header-anchor" href="#这些免疫细胞随后会产生白介素和肿瘤坏死因子等细胞因子"><span>这些免疫细胞随后会产生白介素和肿瘤坏死因子等细胞因子，</span></a></h1><h1 id="导致细胞因子风暴、全身器官衰竭或休克" tabindex="-1"><a class="header-anchor" href="#导致细胞因子风暴、全身器官衰竭或休克"><span>导致细胞因子风暴、全身器官衰竭或休克；</span></a></h1><p>主要症状包括：</p><h1 id="致发热反应" tabindex="-1"><a class="header-anchor" href="#致发热反应"><span>致发热反应；</span></a></h1><h1 id="白细胞反应" tabindex="-1"><a class="header-anchor" href="#白细胞反应"><span>白细胞反应；</span></a></h1><h1 id="内毒素血症" tabindex="-1"><a class="header-anchor" href="#内毒素血症"><span>内毒素血症；</span></a></h1><h1 id="内毒素休克" tabindex="-1"><a class="header-anchor" href="#内毒素休克"><span>内毒素休克；</span></a></h1><p>对于中老年人、慢性感染、<br> 和免疫系统紊乱的人群，<br> 往往会发生微循环障碍、<br> 血液流变异常、<br> 和组织缺氧。<br> 该检测可以对这些症状进行预警。</p><h2 id="血栓弹力图" tabindex="-1"><a class="header-anchor" href="#血栓弹力图"><span>血栓弹力图</span></a></h2><p>反映血液凝固动态变化的指标；</p><h1 id="纤维蛋白的形成速度" tabindex="-1"><a class="header-anchor" href="#纤维蛋白的形成速度"><span>纤维蛋白的形成速度，</span></a></h1><h1 id="溶解状态和凝状的坚固性" tabindex="-1"><a class="header-anchor" href="#溶解状态和凝状的坚固性"><span>溶解状态和凝状的坚固性，</span></a></h1><p>和弹力度。<br> 用于评价人凝血及纤溶系统的功能；</p><h1 id="辅助判断出血或血栓风险" tabindex="-1"><a class="header-anchor" href="#辅助判断出血或血栓风险"><span>辅助判断出血或血栓风险；</span></a></h1><h1 id="指导成分输血" tabindex="-1"><a class="header-anchor" href="#指导成分输血"><span>指导成分输血；</span></a></h1><h1 id="指导药物使用" tabindex="-1"><a class="header-anchor" href="#指导药物使用"><span>指导药物使用；</span></a></h1><p>例如华法林、诺其、比伐卢定、tPA或止血环酸等。<br> 该检测可以对多种疾病进行预警。</p><p>血栓性疾病，包括：</p><ul><li>肾病综合征、尿毒症、冠状动脉粥样硬化性心脏病(冠心病)、心绞痛、心肌梗塞、脑梗塞(脑梗塞)、动静脉血栓形成等；</li></ul><p>血小板异常性疾病，包括：</p><ul><li>原发性和继发性血小板减少症；</li><li>血小板功能异常性疾病；</li></ul><p>凝血因子缺陷性疾病，包括：</p><ul><li>血友病类出血性疾病；</li></ul><p>纤溶亢进性疾病，包括：</p><ul><li>原发性纤溶症；<br> 播散性血管内凝血(弥散性血管内凝血)的继发性纤溶。</li></ul><h2 id="心梗蛋白组学分析" tabindex="-1"><a class="header-anchor" href="#心梗蛋白组学分析"><span>心梗蛋白组学分析</span></a></h2><p>心肌标志物包括：</p><h1 id="肌红蛋白-myoglobin-mb" tabindex="-1"><a class="header-anchor" href="#肌红蛋白-myoglobin-mb"><span>肌红蛋白(myoglobin, Mb)</span></a></h1><ul><li>早期诊断心肌梗塞(AMI)最重要的指标；</li></ul><h1 id="杂化型肌酸激酶同工酶-creatine-kinase-isoenzymes-ck-mb" tabindex="-1"><a class="header-anchor" href="#杂化型肌酸激酶同工酶-creatine-kinase-isoenzymes-ck-mb"><span>杂化型肌酸激酶同工酶(creatine kinase isoenzymes, CK-MB)</span></a></h1><ul><li>临床医师诊断AMI最信赖的心肌标志物；</li></ul><h1 id="心肌肌钙蛋白i-t-cardiac-troponin-ctni-t" tabindex="-1"><a class="header-anchor" href="#心肌肌钙蛋白i-t-cardiac-troponin-ctni-t"><span>心肌肌钙蛋白I/T(cardiac troponin, cTnI/T)</span></a></h1><ul><li>心肌损伤检测的金标准；</li></ul><h2 id="抗衰治疗" tabindex="-1"><a class="header-anchor" href="#抗衰治疗"><span>抗衰治疗</span></a></h2><h3 id="研究课题" tabindex="-1"><a class="header-anchor" href="#研究课题"><span>研究课题</span></a></h3><p>中国医师协会国家课题：“单细胞转录谱图特征与睡眠障碍精准医疗技术的研究”；<br> 糖尿病合并皮肤疾患靶点治疗及细胞功能表达水平研究(白求恩公益基金会)；<br> 恶性肿瘤特异性生长因子在肿瘤诊断中的应用研究(白求恩公益基金会)；<br> 太赫兹无标记检测方法鉴定循环肿瘤细胞的临床研究(国家973计划)；<br> 干细胞的太赫兹广谱分析技术研究(国家973计划)；<br> 白介素-2修饰脐带间充质干细胞对白血病HL-60细胞株增殖、分化的影响(四川省卫生厅科研项目)；<br> 睡眠障碍机制与临床实验项目(四川省继续教育)；<br> 四川省卫生厅科研课题：“IL-2修饰脐带间充质干细胞对白血病HL-60细胞株增殖分化的影响”；</p><h2 id="期望和关注点" tabindex="-1"><a class="header-anchor" href="#期望和关注点"><span>期望和关注点</span></a></h2><h1 id="应用场景和潜在市场" tabindex="-1"><a class="header-anchor" href="#应用场景和潜在市场"><span>应用场景和潜在市场</span></a></h1><p>依托中国医师协会和世界华人医师协会，<br> 与研究型和教学型医院的课题组进行合作并提供服务。</p><p>为产品或服务提供理论依据，包括各种仁钦制剂和过继性细胞回输服务。</p><h2 id="背景资料" tabindex="-1"><a class="header-anchor" href="#背景资料"><span>背景资料</span></a></h2><h3 id="血液科学" tabindex="-1"><a class="header-anchor" href="#血液科学"><span>血液科学</span></a></h3><p>血液科研究的基础医学领域主要包括造血干细胞研究、单细胞技术应用、RNA编辑调控造血干细胞分化等。<br> 而目前血液科基础医学的研究现状为跨物种研究、靶向治疗新发现、精准治疗新方案等。</p><h3 id="血液科基础医学研究领域" tabindex="-1"><a class="header-anchor" href="#血液科基础医学研究领域"><span>血液科基础医学研究领域：</span></a></h3><h4 id="造血干细胞研究" tabindex="-1"><a class="header-anchor" href="#造血干细胞研究"><span>造血干细胞研究：</span></a></h4><p>典型研究成果如单细胞解析造血干细胞异质性与骨髓增殖性肿瘤 (MPN) 致病及治疗的关联，揭示了MPN发病机制与造血干细胞 (HSC) 谱系偏向相关，为液体肿瘤和实体肿瘤的研究提供了新视角。</p><h4 id="单细胞技术应用" tabindex="-1"><a class="header-anchor" href="#单细胞技术应用"><span>单细胞技术应用：</span></a></h4><ul><li><p>白血病和淋巴瘤的诊断和治疗：<br> 单细胞技术可以用于检测白血病和淋巴瘤细胞中的基因突变和表达模式，从而帮助医生确定最佳的治疗方案。</p></li><li><p>造血干细胞移植：<br> 单细胞技术可以用于鉴定和分离造血干细胞，从而提高移植成功率和减少移植后的并发症。</p></li><li><p>免疫疗法：<br> 单细胞技术可以用于研究免疫系统中不同类型细胞的功能和相互作用，从而为开发新型免疫疗法提供理论基础。</p></li><li><p>血液病的早期诊断和预防：<br> 单细胞技术可以用于检测血液中的微小变化，从而及早发现潜在的血液病风险。</p></li></ul><h4 id="rna编辑调控造血干细胞分化" tabindex="-1"><a class="header-anchor" href="#rna编辑调控造血干细胞分化"><span>RNA编辑调控造血干细胞分化：</span></a></h4><p>首次绘制了小鼠造血全谱系的RNA编辑图谱，及其动态变化，揭示了Azin1这一全新的造血调控因子及其RNA编辑协同DDX1调控造血干细胞分化的新机制。</p><h4 id="巨核细胞异质性" tabindex="-1"><a class="header-anchor" href="#巨核细胞异质性"><span>巨核细胞异质性：</span></a></h4><p>揭秘了成年骨髓巨核细胞的异质性，为疾病条件下巨核细胞亚群组成和功能的变化提供了重要参考。</p><h3 id="血液科基础医学研究现状" tabindex="-1"><a class="header-anchor" href="#血液科基础医学研究现状"><span>血液科基础医学研究现状：</span></a></h3><h4 id="跨物种研究" tabindex="-1"><a class="header-anchor" href="#跨物种研究"><span>跨物种研究：</span></a></h4><p>利用猴囊胚的体外长时程3D培养体系，首次在单细胞水平系统揭示了猴早期造血起源和谱系特化的动态规律，开创了人、猴、鼠跨物种研究的新思路。</p><h4 id="靶向治疗新发现" tabindex="-1"><a class="header-anchor" href="#靶向治疗新发现"><span>靶向治疗新发现：</span></a></h4><p>鉴定和靶向急性T淋巴细胞白血病 (T-ALL) 的白血病干细胞，首次揭示了PD-1能够特异性识别T-ALL的白血病干细胞，阻断PD-1可有效清除这些干细胞。</p><h4 id="精准治疗新方案" tabindex="-1"><a class="header-anchor" href="#精准治疗新方案"><span>精准治疗新方案：</span></a></h4><p>基于分子分型的弥漫性大B细胞淋巴瘤精准治疗新方案，证实基于分子分型精准联合靶向药物的R-CHOP-X方案的有效性和安全性。</p><h4 id="肿瘤相关血小板异常" tabindex="-1"><a class="header-anchor" href="#肿瘤相关血小板异常"><span>肿瘤相关血小板异常：</span></a></h4><p>解开了肿瘤病人贫血和血小板增多的谜团，阐明了调控MEP异常分化的信号通路AHR-RUNX1，逆转肿瘤病人和人源化小鼠MEP异常分化。</p><h4 id="异基因造血干细胞移植" tabindex="-1"><a class="header-anchor" href="#异基因造血干细胞移植"><span>异基因造血干细胞移植：</span></a></h4><p>单细胞解析异基因造血干细胞移植患者造血再生规律，为深入理解异基因移植生态提供了宝贵证据。</p><h4 id="泛癌种生物信息学分析" tabindex="-1"><a class="header-anchor" href="#泛癌种生物信息学分析"><span>泛癌种生物信息学分析：</span></a></h4><p>自然杀伤 (NK) 细胞在不同癌症类型之间的组成及表型异质性刻画，发现了髓系细胞在调节NK细胞抗肿瘤功能方面的潜力。</p><h3 id="利用网络生物学进行研究阿尔茨海默症" tabindex="-1"><a class="header-anchor" href="#利用网络生物学进行研究阿尔茨海默症"><span>利用网络生物学进行研究阿尔茨海默症</span></a></h3><p>阿尔茨海默病 (AD)是一种复杂的多基因多因素神经退行性疾病，其病理机制仍然在研究中不断深化。<br> 网络生物学作为一种新兴的研究方法，提供了对阿尔茨海默病机制的深入理解，能够帮助我们发现新的疾病生物标志物和药物靶点。</p><h4 id="网络生物学的基本概念" tabindex="-1"><a class="header-anchor" href="#网络生物学的基本概念"><span>网络生物学的基本概念:</span></a></h4><p>网络生物学是通过构建生物分子之间相互作用的网络来理解生物过程的一种方法。<br> 这种方法强调生物系统的整体性，认为生物学特征不仅仅是单个基因或蛋白质的功能，而是它们在网络中的相互作用所形成的功能。<br> 通过分析这些网络，研究人员可以识别出关键的生物标志物和药物靶点。</p><p>网络生物学 (Network Biology) 是一门研究生物系统中相互作用网络的学科，它结合了生物学、计算机科学、数学和物理学等多个领域的知识。<br> 网络生物学的目标是通过构建和分析生物分子之间的相互作用网络，来揭示生物系统的组织结构、功能和调控机制。</p><p>在网络生物学中，生物分子 (如基因、蛋白质、代谢物等) 被视为网络中的节点，它们之间的相互作用 (如基因调控、蛋白质相互作用、代谢途径等) 被视为网络中的边。<br> 通过构建这些生物网络，研究人员可以更好地理解生物系统的复杂性，发现新的生物标志物和药物靶点，为疾病的诊断和治疗提供新的思路。</p><h4 id="阿尔茨海默病的病理机制" tabindex="-1"><a class="header-anchor" href="#阿尔茨海默病的病理机制"><span>阿尔茨海默病的病理机制:</span></a></h4><p>阿尔茨海默病的主要病理特征包括淀粉样β（Aβ）斑块和Tau蛋白的神经纤维缠结。这些病理改变与细胞的凋亡、神经炎症及突触功能障碍密切相关。网络生物学方法能够通过分析这些相关分子之间的关系，揭示出更为复杂的病理机制。</p><p>淀粉样蛋白和Tau蛋白：网络生物学的研究表明，Aβ和Tau蛋白不仅在各自的路径中发挥功能，还通过相互作用影响其他相关蛋白质的功能。这种相互作用可能导致细胞内的信号传导紊乱，从而加速神经元的损伤和死亡。<br><a href="10.14283/jpad.2022.29">ref</a><br><a href="10.1016/j.ibneur.2023.11.003">ref</a></p><p>神经炎症：近年来的研究进一步强调了神经炎症在阿尔茨海默病发展中的重要性。网络生物学的视角使得研究者能够识别与神经炎症相关的分子通路，这些通路可以作为潜在的治疗靶点。例如，微胶质细胞的活化与Aβ沉积密切相关，研究这些细胞的网络机制可以为炎症相关的治疗策略提供依据。<br><a href="10.3390/diagnostics12122975">ref</a><br><a href="10.14283/jpad.2023.109">ref</a></p><h4 id="发现新的生物标志物和药物靶点" tabindex="-1"><a class="header-anchor" href="#发现新的生物标志物和药物靶点"><span>发现新的生物标志物和药物靶点:</span></a></h4><p>网络生物学可以帮助识别新的生物标志物和药物靶点。<br> 通过对基因表达数据进行网络分析，研究人员能够发现与阿尔茨海默病相关的特定基因和路径。<br> 这些发现不仅可以用于早期诊断，还可以指导个性化治疗。</p><p>基因签名的识别：<br> 基因签名是指一组特定的基因，这些基因在某种特定条件下 (如疾病、治疗反应等)表现出相似的表达模式。<br> 基因签名可以用于预测疾病的发生、发展、预后以及患者对治疗的反应等。<br> 通过对基因签名的研究，可以帮助我们更好地理解疾病的分子机制，为疾病的诊断和治疗提供新的策略。<br> 不同的系统生物学和生物信息学方法已经被应用于识别与阿尔茨海默病相关的基因签名。<br> 这些基因通常与神经炎症、细胞凋亡和突触可塑性等过程相关联。<br> 这些基因的表达模式可以作为潜在的生物标志物，用于疾病的早期诊断和预后评估。<br><a href="10.1016/j.imu.2020.100439">ref</a><br><a href="10.1101/2024.08.10.607237">ref</a></p><p>多靶点治疗策略：<br> 阿尔茨海默病的异质性使得单一靶点治疗往往效果有限。<br> 网络生物学的研究强调了多靶点治疗的必要性和有效性。<br> 这种策略通过同时靶向多个相关的生物通路，可以更全面地应对阿尔茨海默病的复杂性。<br><a href="10.3390/ijms24065383">ref</a></p><h4 id="未来的研究方向" tabindex="-1"><a class="header-anchor" href="#未来的研究方向"><span>未来的研究方向:</span></a></h4><p>尽管网络生物学在阿尔茨海默病研究中已经展现出巨大潜力，但仍有许多挑战需要克服。<br> 例如，如何有效整合来自不同组学层次 (如基因组、转录组和蛋白质组)的数据，以构建更加精准的生物网络模型。<br> 此外，临床转化研究也需要更多的支持，以验证网络生物学提出的理论和假设在实际治疗中的有效性。</p><h3 id="多组学分析" tabindex="-1"><a class="header-anchor" href="#多组学分析"><span>多组学分析</span></a></h3><h4 id="基因组学数据分析" tabindex="-1"><a class="header-anchor" href="#基因组学数据分析"><span>基因组学数据分析：</span></a></h4><p>利用高通量测序技术 (如全基因组关联研究，GWAS) 来识别与阿尔兹海默病相关的遗传变异。<br> 通过分析患者和对照组的基因型数据，可以找到与疾病风险相关的遗传标记。</p><h4 id="转录组学分析" tabindex="-1"><a class="header-anchor" href="#转录组学分析"><span>转录组学分析：</span></a></h4><p>使用RNA测序 (RNA-Seq) 技术来分析患者和对照组的基因表达谱。<br> 通过比较两组之间的差异表达基因，可以发现与阿尔兹海默病发病机制相关的关键基因。</p><h4 id="蛋白质组学分析" tabindex="-1"><a class="header-anchor" href="#蛋白质组学分析"><span>蛋白质组学分析：</span></a></h4><p>利用质谱技术分析患者和对照组的蛋白质表达谱。<br> 通过比较两组之间的差异表达蛋白，可以发现与阿尔兹海默病相关的蛋白质标志物。</p><h4 id="代谢组学分析" tabindex="-1"><a class="header-anchor" href="#代谢组学分析"><span>代谢组学分析：</span></a></h4><p>通过核磁共振 (NMR) 或质谱技术分析患者和对照组的代谢物谱。<br> 这有助于发现与阿尔兹海默病相关的代谢途径和潜在的生物标志物。</p><h3 id="网络生物学分析" tabindex="-1"><a class="header-anchor" href="#网络生物学分析"><span>网络生物学分析：</span></a></h3><p>整合上述多组学数据，构建基因、蛋白质、代谢物之间的相互作用网络。<br> 通过网络分析，可以揭示阿尔兹海默病的核心调控模块和关键节点，为诊疗靶点的筛选提供依据。</p><h3 id="药物靶点预测" tabindex="-1"><a class="header-anchor" href="#药物靶点预测"><span>药物靶点预测：</span></a></h3><p>基于已知的药物靶点数据库 (如DrugBank、ChEMBL等) ，对筛选出的候选靶点进行药物作用机制和安全性评估。<br> 同时，可以利用分子对接、药效团分析等计算化学方法，预测新的药物靶点。</p><h3 id="机器学习和人工智能" tabindex="-1"><a class="header-anchor" href="#机器学习和人工智能"><span>机器学习和人工智能：</span></a></h3><p>利用机器学习算法 (如支持向量机、随机森林、深度学习等) 对多组学数据进行特征选择和分类。<br> 这有助于提高阿尔兹海默病诊疗靶点的筛选准确性和效率。</p><h3 id="临床验证" tabindex="-1"><a class="header-anchor" href="#临床验证"><span>临床验证：</span></a></h3><p>将计算生物医学平台筛选出的候选靶点在临床样本中进行验证，如通过免疫组化、Western blot等技术检测靶点在患者和对照组中的表达差异，以评估其作为诊疗靶点的可行性。</p><h4 id="选择合适的动物模型" tabindex="-1"><a class="header-anchor" href="#选择合适的动物模型"><span>选择合适的动物模型：</span></a></h4><p>根据预测的靶点，选择适合的动物模型进行实验。<br> 例如，可以选择小鼠、果蝇等模式生物，或者使用人类诱导多能干细胞(iPSCs)和人类胚胎干细胞(hESCs)等体外模型。</p><h4 id="设计实验方案" tabindex="-1"><a class="header-anchor" href="#设计实验方案"><span>设计实验方案：</span></a></h4><p>根据预测的靶点和动物模型的特点，设计相应的实验方案。<br> 例如，可以使用基因编辑技术(如CRISPR/Cas9)来敲除或过表达相关基因，观察其对阿尔兹海默症的影响；<br> 或者可以使用药物干预来验证预测的靶点是否具有治疗作用。</p><h4 id="进行动物实验" tabindex="-1"><a class="header-anchor" href="#进行动物实验"><span>进行动物实验：</span></a></h4><p>按照实验方案进行动物实验，并记录相关数据。<br> 例如，可以使用行为学测试、生化指标检测等方法来评估阿尔兹海默症的症状和病理变化。</p><h4 id="分析实验结果" tabindex="-1"><a class="header-anchor" href="#分析实验结果"><span>分析实验结果：</span></a></h4><p>对实验结果进行统计分析和解释，以验证预测的靶点是否具有实际应用价值。<br> 例如，可以使用生物信息学方法来分析基因表达谱、蛋白质互作网络等数据，以确定相关靶点的生物学功能和作用机制。</p><h4 id="进行临床验证" tabindex="-1"><a class="header-anchor" href="#进行临床验证"><span>进行临床验证：</span></a></h4><p>如果动物实验结果证明了预测的靶点具有治疗作用，可以进一步进行临床验证。<br> 例如，可以设计临床试验来评估新药物的安全性和有效性，或者使用生物标志物检测等方法来监测疾病的进展和治疗效果。</p><h1 id="计算医学" tabindex="-1"><a class="header-anchor" href="#计算医学"><span>计算医学</span></a></h1><p>随着数据的飞速积累和方法加速更新换代，<br> 未来医学范式将向以数据和计算方法为主的计算医学(Computational Medicine，CM)发生转变。<br> 通过计算模型和超算技术，<br> 这种新的医学范式以逼近真实的方式理解生命机理和疾病机制，<br> 并将提高疾病预测、临床诊疗和健康维护水平，<br> 使个性化决策成为可能，<br> 从而可能彻底改变从单个病人护理到政策制定的整个医学领域。</p><h2 id="计算医学的兴起" tabindex="-1"><a class="header-anchor" href="#计算医学的兴起"><span>计算医学的兴起</span></a></h2><p>医学实践具有相当大的不确定性，<br> 且一直存在。<br> 传统医学面对这些决策中的不确定性，<br> 通常的处理方式是通过从经验中积累的专业知识进行判断，<br> 后发展为通过循证医学的形式对研究进行系统的评估实现。<br> 另一方面，<br> 循证医学主要以群体证据作为核心依据，<br> 往往无法有效的解释个体差异。</p><p>随着基因测序、检查检验设备、可穿戴设备等新的检测方法和工具的不断涌现，<br> 获取个人不同尺度上的健康、疾病数据成为可能。<br> 这也导致医疗健康相关的数据指数级增长。<br> 同时，<br> 大数据赋予了医生和临床科研人员更多、更细致的维度去了解疾病发生发展过程，<br> 大大拓展了医学研究的深度和广度。</p><p>这些复杂数据的处理已经远远超出个人的处理能力，<br> 急需新的方式与手段帮助医生从多维、立体、融合的数据中摸索出规律，<br> 从而更精确地进行疾病的预测、预防、诊断和治疗。<br> 因此，<br> 以数据和计算方法为主的计算医学开始出现并发展。<br> 这也预示着未来医学发展范式的转向。</p><p>早在上世纪八十年代，<br> 如何在医学领域里应用计算技术的研究就已经开始。<br> 1994年，<br> 于美国奥斯汀举行的首届计算医学、公共卫生和生物科技大会，<br> 计算医学已经开始显现成为医学重要前沿研究方向的趋势。<br> 这在当时仍然是一个非常小众的研究，<br> 只有一小部分生物医学科学家在使用计算方法开展数学建模。<br> 2012年10月，<br> 美国约翰霍普金斯大学生物医学工程教授Raimond L.Winslow在《科学转化医学》(Science Translational Medicine)上发表了一篇名为《计算医学：<br> 从模型到临床》(Computational Medicine: Translating Models to Clinical Care)的综述性文章。<br> 在文中，<br> 他指出计算医学已经从理论走向实践。<br> Winslow也因此被公认为计算医学新领域的创始人。<br> 近年来，<br> 随着数据的飞速积累以及大数据的处理挖掘方法不断成熟，<br> 以深度学习为代表的人工智能方法在图像识别、自然语言处理等领域取得了令人瞩目的成就。<br> 这些数据和技术领域的革新也推动了计算医学进入新的快速发展周期。</p><h2 id="计算医学的进展" tabindex="-1"><a class="header-anchor" href="#计算医学的进展"><span>计算医学的进展</span></a></h2><p>计算医学作为医学、工程与计算机的交叉学科，<br> 是多个学科专业共同的交叉研究领域。<br> 从文献学科分类统计来看，<br> 计算医学主要与放射学、核医学和医学影像、生物化学和分子生物学、数学与计算生物学、计算机科学与跨学科应用、药理学与制药、生物医学工程、生物化学研究方法学、工程、电器与电子、多学科科学、计算机科学及人工智能等学科密切相关。<br> 对文献关键词统计结果进行分析，<br> 计算医学领域排名前十的关键词分别为：<br> 模型(model)、癌症(cancer)、表达(expression)、预测(prediction)、仿真(simulation)、识别(identification)、系统生物学(system biology)、精准医学(precision medicine)、系统(system)和算法(algorithm)。<br> 在研究领域选择上不同国家各有侧重。<br> 中美两国的研究领域涉及面较广，<br> 各类研究关键词均有相关文献。<br> 具体对比来看，<br> 中国的研究关键词排名前三的为药物发现(drug discovery)、精准医疗(precision medicine)、预测(prediction)，<br> 美国研究关键词排名前三的则依次为精准医疗(precision medicine)、模型(model)和机器学习(machine learning)。<br> 就研究关键词的发文数量来看，<br> 中国在计算医疗技术领域的模型构建、仿真模拟以及机器学习研究和应用领域的精准医疗、个性化医疗等五个方面的研究关注度与美国差距较大。</p><p>根据对各国近20年来研究热点变迁的分析来看，<br> 计算医学正从原有理论、模型等基础性研究向应用研究转变。<br> 2009年以前，<br> 各国研究主题非常多样，<br> 较为集中的主题主要集中在“方法(method)”和“模型(model)”，<br> 在2002-2009年和2006-2009年分别成为日本、美国的研究热点。<br> 2010年以后，<br> 各国的计算医学研究热点开始出现更多重叠。<br> 其中，<br> “癌症(cancer)”在2014-2017年成为多个国家计算医学领域的研究热点；<br> “表达(expression)”先后成为韩国、英国和中国在计算医学领域的研究重点；<br> 2018-2021年，<br> “精准医疗(precision medicine)”成为美国计算医学领域研究热点。</p><p>通过将前述1980-2021年的5257篇相关文献进行关键词聚类，<br> 得到了10个非常清晰的计算医学聚类类别。<br> 排名前三的分别是“精准医学”“机器学习”“计算研究”领域。<br> 虚拟筛选靶点发现等药物发现相关的“计算研究”也是最新的领域方向，<br> 平均发文时间为2013年。<br> 这些聚类结果主要又可分为三类：<br> 第一类为计算建模相关研究，<br> 从最早的放射建模相关内容到血流动力学建模、蒙特卡洛模拟、射线与疾病相关研究。<br> 其中，<br> 最突现的关键词为模型、仿真和系统。<br> 第二类为计算组学相关研究，<br> 主要包括基因序列研究、非编码RNA和基因组学应用相关研究，<br> 并向精准医疗和药物筛选研究扩展。<br> 其关键节点包括癌症、数据库和基因表达。<br> 第三类为基于人工智能的相关研究，<br> 包括机器学习领域和精准计算机断层扫描应用领域。</p><h2 id="计算医学的定义" tabindex="-1"><a class="header-anchor" href="#计算医学的定义"><span>计算医学的定义</span></a></h2><p>纽约大学从计算技术和医学的关系层面，<br> 将计算医学描述为“计算医学是利用数据驱动的分析来发现复杂动态生物系统的结构、功能和进化”。<br> 约翰霍普金斯大学计算医学研究所则更强调计算技术对医学的价值：<br> “计算医学是计算机科学和医学交界的一个跨学科领域，<br> 计算方法被开发来了解人类疾病。<br> 数学、信息学和计算模型被应用于为疾病的机制、诊断和治疗提供见解，<br> 并最终改善病人的护理”。</p><p>作为一门新兴学科，<br> 计算医学的核心是通过应用数学、计算科学来理解人类疾病的机理，<br> 为医学服务提供新洞见，<br> 提高并改善疾病诊疗水平。<br> 广义上，<br> 应用计算机和计算模型来支持医疗保健服务的医学研究的所有方面都可以被纳入到计算医学范畴。</p><p>另一个与计算医学密切相关的学科为计算生物学(Computational Biology)。<br> 根据美国国家卫生研究院的定义，<br> 计算生物学是指开发和应用数据分析及理论的方法、数学建模和计算机仿真技术，<br> 用于生物学、行为学和社会群体系统的研究的学科。<br> 不难发现，<br> 计算医学和计算生物学有部分交叉，<br> 例如在计算基因组学领域。<br> 相对而言，<br> 计算生物学作为生物学的一个分支，<br> 归属于基础科学，<br> 主要是为医学研究提供基础支撑；<br> 计算医学则更偏向于应用科学，<br> 关注的是人体健康与疾病相关问题的研究。</p><p>计算医学的研究重点大致经历了三个阶段的演变：<br> 人体仿真与计算建模研究阶段、基因大数据驱动的计算医学应用研究阶段以及基于人工智能的计算医学与应用研究阶段。<br> 伴随现代医学向微观和宏观两方面的发展，<br> 计算医学的研究内容逐渐包含了计算基因组学、医学信息学、计算神经遗传学建模、计算神经科学、人体建模、数字人体、精准医学等领域。</p><p>作为一门较高难度的交叉学科，<br> 计算医学需要综合来自计算机科学、数学、统计学、生物化学、化学工程、生物医学工程、生物物理学、分子生物学、遗传学、生态学、解剖学等学科的知识。<br> 计算医学会涉及到使用近现代的数学工具来对生物对象进行数学建模，<br> 所以对数学的要求会比较高，<br> 尤其是动力系统和概率。<br> 而微积分和线性代数又是动力系统和概率的基础。<br> 其他必要的基础知识还包括生物学基础、医学基础、计算机基础和工程基础领域知识。</p><h2 id="编年史" tabindex="-1"><a class="header-anchor" href="#编年史"><span>编年史</span></a></h2><h3 id="机器学习" tabindex="-1"><a class="header-anchor" href="#机器学习"><span>机器学习</span></a></h3><p>1957,<br> description of perceptron;<br> 1986,<br> backpropagation paper;<br> 2000s,<br> rise of cloud computing;<br> 2010s,<br> rise of modern deep learning;<br> 2012,<br> alexnet wins imagenet;<br> 2014,<br> first VAE and GAN;</p><h3 id="医药进展" tabindex="-1"><a class="header-anchor" href="#医药进展"><span>医药进展</span></a></h3><p>1982,<br> Recombinant human insulin;<br> 1980s,<br> Transgenic mouse;<br> 1990s,<br> HTP screening;<br> 1997,<br> First humanized antibody;<br> 2000,<br> Yeast display for discovery;<br> 2018,<br> Sales of biologics surpass small molecules;</p><h3 id="biological-engineering" tabindex="-1"><a class="header-anchor" href="#biological-engineering"><span>biological engineering</span></a></h3><p>1980s,<br> rise of omics era;<br> 1990s,<br> invention of NGS DNA sequencing;<br> 1997,<br> First computationally designed protein;<br> 2003,<br> De novo design of a protein fold;<br> 2010s,<br> Mass DNA synthesis;<br> 2014,<br> PDB reaches 100k structures;</p>',449)]))}const c=e(h,[["render",i]]),o=JSON.parse('{"path":"/projects/project-collaboration-meeting-cdboe-hospital.html","title":"京东方医院合作项目沟通会","lang":"zh-TW","frontmatter":{},"git":{"createdTime":1725517729000,"updatedTime":1729259518000,"contributors":[{"name":"tiikerihvgo","username":"","email":"warnghuu@yandex.com","commits":5},{"name":"afroditehvgo","username":"","email":"warnghuu@yandex.com","commits":1}]},"readingTime":{"minutes":71.9,"words":21569},"filePathRelative":"projects/project-collaboration-meeting-cdboe-hospital.md","excerpt":"\\n<h2>会议目标和议程</h2>\\n<h3>背景</h3>\\n<h4>合作背景</h4>\\n<h4>合作目的</h4>\\n<p>拟以京东方成都医院为第一主研单位，成都仁钦生物科技有限公司为合作单位，开展慢病和老年病的研究。<br>\\n包括：<br>\\n阿尔兹海默症、睡眠障碍、四高症等。</p>\\n<h4>合作原则</h4>\\n<h3>合作目标与范围</h3>\\n<h4>具体目标</h4>\\n<h4>研究范围和领域</h4>\\n<h3>合作方责任与义务</h3>\\n<h4>研究所的责任</h4>\\n<h4>医院的责任</h4>\\n<h4>双方共同责任</h4>\\n<h3>合作模式与流程</h3>\\n<h4>合作模式（如联合研究、资源共享等）</h4>"}');export{c as comp,o as data};
